/* generálva: build.py — ne szerkeszd kézzel */
window.SERE_CONTENT_SK=[{"id":"1","title":"Systém výcviku SERE","sub":"I. časť, 1. lekcia","sections":[{"id":"1.1","title":"Úvod","web":false,"blocks":[{"t":"p","x":"Náš svet je čoraz civilizovanejší a pritom slabnú inštinkty potrebné na prežitie. V záujme ochrany vojakov treba venovať osobitnú pozornosť obnoveniu a rozvoju ich schopnosti prežiť."},{"t":"p","x":"SERE je anglická skratka: **S**urvival, **E**vasion, **R**esistance, **E**xtraction – po slovensky Prežitie, Únik, Odpor, Vyzdvihnutie."},{"t":"p","x":"Výcvik zahŕňa taktiky, metódy a postupy, ktoré znižujú šancu zajatia izolovanej osoby a výrazne zlepšujú jej vyhliadky na prežitie v rôznom prostredí. Ak padne do zajatia, dokáže odolávať, prežiť zajatie a ak to situácia dovolí, utiecť."}]},{"id":"1.2","title":"O učive","web":false,"blocks":[{"t":"p","x":"Jednotný systém výcviku SERE zabezpečuje, aby každý poznal pravidlá SERE v podrobnosti zodpovedajúcej svojej úrovni – „A“, „B“, „C“ –, a tak sa pri izolovaní znížilo riziko straty a zajatia síl."},{"t":"quote","x":"Teória je nevyhnutná, ale nikdy nenahradí prax. Keď to počuješ, zabudneš; keď to vidíš, poznáš; keď to robíš, vieš to!"},{"t":"li","items":["Nízke riziko → SERE „A“","Stredné riziko → SERE „B“","Vysoké riziko → SERE „C“"]}]},{"id":"1.3","title":"Všeobecne o výcviku SERE","web":false,"blocks":[{"t":"p","x":"V Maďarských ozbrojených silách upravuje systém výcviku SERE odborný predpis náčelníka generálneho štábu."}]},{"id":"1.4","title":"Základné pojmy","web":false,"blocks":[{"t":"li","items":["**ISOP – izolovaná osoba (Isolated Personnel):** vojak alebo civilista oddelený od svojej jednotky či organizácie, ktorý stratil pozitívnu a/alebo procedurálnu kontrolu, a preto musí použiť techniky prežitia, úniku a odporu, aby sa mohol vrátiť.","**Prežitie (Survival):** všetky činnosti, vďaka ktorým izolovaná osoba zostane nažive a udrží si telesné a duševné zdravie v rôznych podmienkach prostredia.","**Únik (Evasion):** postupy, ktorými izolovaná osoba unikne odhaleniu a kontaktu s nepriateľskými či potenciálne nepriateľskými silami a osobami, alebo ktoré umožnia návrat.","**Odpor (Resistance):** taktiky, metódy a postupy, ktorými izolovaná osoba v zajatí dokáže znížiť účinnosť výsluchových taktík väzniteľov.","**Vyzdvihnutie (Extraction):** záchrana izolovanej osoby z nepriateľského alebo potenciálne nepriateľského územia.","**JPR – spoločná záchrana osôb (Joint Personnel Recovery):** súhrn vojenského, diplomatického a civilného úsilia o záchranu a reintegráciu izolovaných osôb."]}]},{"id":"1.5","title":"Zásady","web":false,"blocks":[{"t":"p","x":"Skúsenosti z nedávnych operácií ukazujú, že šanca izolovania, zajatia a násilného výsluchu vojakov aj civilistov je významná. Účastníci musia vedieť prežiť, uniknúť nepriateľovi, pripraviť sa na vyzdvihnutie alebo sa prepracovať späť k vlastným; v prípade potreby odolávať násilnému výsluchu a pomôcť pri vlastnej záchrane vrátane úteku zo zajatia."},{"t":"p","x":"Rozsah moderných bojísk a vývoj techniky spôsobujú, že naše jednotky operujú vo stále väčších vzdialenostiach, čo zvyšuje šancu izolovania. ISOP treba pripraviť na záchranu a sebazáchranu, vycvičiť ho a zabezpečiť potrebnú výstroj."},{"t":"p","x":"Strata vojakov vycvičených na modernú techniku môže znamenať rozhodujúcu stratu spôsobilosti, preto ich treba pripraviť na prežitie, únik alebo prípravu vyzdvihnutia."},{"t":"p","x":"Bojiská väčšinou majú systém JPR, ktorého účinnosť závisí okrem výstroja aj od pripravenosti zachraňovanej osoby."}]},{"id":"1.6","title":"Systém výcviku SERE","web":false,"blocks":[{"t":"p","x":"Výcvik môže byť teoretický alebo praktický podľa úrovne, prostredia, hrozby a bojiska. Treba sa usilovať, aby sa výcvik robil presne s výstrojom, ktorý sa použije v operáciách. Úspech závisí od jednotného výcviku, prípravy a vhodného výstroja – ich absencia môže byť aj strategickým rizikom."},{"t":"p","x":"Čo nie je v súlade s platným programom výcviku SERE, nemožno považovať za výcvik SERE. Program pripravuje stála skupina SERE a schvaľuje ho riaditeľstvo výcviku."},{"t":"p","x":"Národný systém sa riadi normou NATO STANAG 7196 (ED 2) – SERE Training Standard, APRP-3.3.7.5 Edition B."}]},{"id":"1.7","title":"Úrovne programu","web":false,"blocks":[{"t":"li","items":["**SERE „A“:** teoretický výcvik osôb s nízkym rizikom izolovania; zabezpečujú ho výcvikové orgány útvarov.","**SERE „B“:** teoretický a praktický výcvik osôb so stredným rizikom; vykonáva ho ústredná výcviková skupina SERE v spolupráci s útvarmi.","**SERE „C“:** výcvik osôb s vysokým rizikom; koordinuje ho odborný garant, vykonáva ústredná výcviková skupina SERE."]},{"t":"ok","x":"Úrovne „B“ a „C“ platia 5 rokov a opakovacím výcvikom sa dajú predĺžiť o 3 roky – bez obmedzenia počtu."}]},{"id":"1.8","title":"Kurz SERE „A“","web":false,"blocks":[{"t":"p","x":"SERE „A“ je teoretický výcvik osôb s nízkym rizikom izolovania. Každá kapitola trvá asi 1–2 hodiny a končí testom s 10 otázkami; hranica úspešnosti je 70 %."}]}]},{"id":"2","title":"Zakladanie ohňa","sub":"I. časť, 2. lekcia – Zakladanie ohňa zapaľovačom, zápalkami a núdzovými prostriedkami","sections":[{"id":"2.1","title":"Význam ohňa","web":false,"blocks":[{"t":"p","x":"Schopnosť založiť oheň je jednou z najdôležitejších zručností na prežitie. Oheň môžeme použiť:"},{"t":"li","items":["na zohriatie, ohrievanie, sušenie odevu;","ako zdroj svetla a na signalizáciu (svetlo, plameň, dym);","na výrobu nástrojov, pečenie a varenie;","na úpravu vody (varenie, drevené uhlie);","na odplašenie zvierat, odpudzovanie hmyzu (dym);","na zlepšenie morálky, drevené uhlie na maskovanie."]},{"t":"ok","x":"Ak sa ohňom zohrievaš, telo spáli menej kalórií na udržanie teploty – potrebuješ menej jedla."},{"t":"warn","x":"Na nepriateľskom území môže svetlo, dym a pach ohňa ľahko prezradiť tvoju polohu. Nestačí poznať metódy – treba zručnosť získanú cvičením."}]},{"id":"2.2","title":"Úvahy","web":false,"blocks":[{"t":"li","items":["Vyhni sa veľkému ohňu: malý oheň potrebuje menej paliva, lepšie sa ovláda a jeho teplo je sústredenejšie.","Oheň nikdy nenechávaj bez dozoru, iba ak si ho bezpečne prikryl alebo uhasil."]},{"t":"ok","x":"Prikrytie: nahrň na oheň studený popol a suchú zeminu, navrchu nechaj dosť vzduchu, aby palivo tlelo. Dá sa znova rozdúchať."}]},{"id":"2.3","title":"Bezpečnosť","web":false,"blocks":[{"t":"p","x":"Treba rozlišovať núdzovú situáciu a mierový výcvik viazaný pravidlami. Vždy maj na pamäti ochranu ľudského života, zvierat, prírody, majetku a zariadení."},{"t":"warn","x":"Nikdy nepodceňuj silu ohňa – v okamihu sa môže vymknúť spod kontroly."},{"t":"warn","x":"V chlade sú popáleniny častejšie ako omrzliny. Používaj ochranné rukavice, multifunkčné kliešte, izolovanú rukoväť."},{"t":"warn","x":"Z vyčerpania a nepozornosti môže zhorieť aj výstroj (rádio, topánky, pončo) – v situácii prežitia to môže byť osudné."},{"t":"warn","x":"V uzavretom alebo zle vetranom priestore hrozí otrava dymom (oxidom uhoľnatým) – zabezpeč vetranie."},{"t":"li","items":["Pri skupinovom alebo párovom výcviku vždy urči strážcu ohňa.","Hasiace prostriedky (voda, piesok, rýľ, lopata) maj poruke."]}]},{"id":"2.4","title":"Prvky ohňa","web":false,"blocks":[{"t":"p","x":"Tri základné prvky úspešného ohňa tvoria **ohňový trojuholník**:"},{"t":"ol","items":["horľavina;","teplo;","kyslík."]},{"t":"p","x":"Obmedzením horľaviny možno urobiť len malý oheň. Ak sa oheň správne neprikladá, môže byť priveľký alebo primalý. Čerstvo zrezané zelené drevo sa ťažko zapaľuje – oheň už musí dobre horieť."},{"t":"ok","x":"Odobratím ktoréhokoľvek prvku (prikrytie, voda, odstránenie paliva) oheň zhasne – tak uvažuj aj pri hasení."}]},{"id":"2.5","title":"Tri úrovne paliva","web":false,"blocks":[{"t":"ol","items":["**Podpaľovač** – ľahko zápalný materiál;","**Triesky** (podpaľovacie drevo);","**Palivo** – palivové drevo."]},{"t":"quote","x":"Keď si myslíš, že máš dosť podpaľovača, triesok a dreva, strojnásob to – a možno to bude stačiť."}]},{"id":"2.6","title":"Podpaľovač","web":false,"blocks":[{"t":"p","x":"Akýkoľvek drobný materiál s nízkou teplotou vznietenia, ktorý vzbĺkne od minimálneho tepla (napr. iskry). Ulož ho tak, aby sa medzi vlasovo tenké, úplne suché vlákna dostal vzduch."},{"t":"ok","x":"Suchý podpaľovač je pre izolovanú osobu kľúčový – maj ho vždy poruke v nepremokavom vrecku."},{"t":"li","items":["Dá sa zbierať v dvoch-troch fázach: počas presunu ho priebežne zbieraj a suš (napr. vo vrecku, pri tele)."]}]},{"id":"2.7","title":"Prírodný podpaľovač","web":false,"blocks":[{"t":"li","items":["rozvláknená kôra niektorých stromov a kríkov: céder, palmové vlákno, **brezová kôra** (horí aj mokrá);","výstelka vtáčích alebo hlodavčích hniezd;","zuhoľnatené trúchnivé drevo;","suchý práchnovec;","páperie glejovky, bodliaka, plamienka, trstiny;","rozdrvené vlákna odumretých rastlín (slama, seno);","jemné suché hobliny;","strúhanka zo živičnatého dreva (smolné drevo);","sušená, rozomletá živica ihličnanov (smola)."]}]},{"id":"2.8","title":"Umelý podpaľovač","web":false,"blocks":[{"t":"li","items":["vata a výrobky z nej: tampón, odličovací tampón;","zuhoľnatená bavlnená látka (char cloth), bavlnené guľôčky, chumáče;","plastové hobliny (napr. lyžička z MRE);","ropné palivá (petrolej, benzín);","oceľová vlna (vzbĺkne aj od kontaktov batérie);","papier, penová hmota;","alkoholový dezinfekčný gél;","strelný prach;","tuhý lieh."]},{"t":"warn","x":"Benzínové pary sú výbušné – len malé množstvo, nalej na studený podpaľovač pred zapálením."}]},{"id":"2.9","title":"Triesky","web":false,"blocks":[{"t":"p","x":"Ďalšia úroveň paliva. Majú vyššiu teplotu vznietenia, treba ich uložiť tak, aby vzbĺkli, keď ich dosiahne plameň podpaľovača. Ich úlohou je zvýšiť teplotu horenia na úroveň, pri ktorej oheň udrží väčšie palivo."},{"t":"p","x":"**Prírodné:** odumreté suché drobné vetvičky; tenko rozštiepené kúsky dreva, bambusu alebo trstiny; hobliny vyrezané zvnútra hrubších konárov; šišky, ihličie; odumreté dolné konáriky ihličnanov."},{"t":"warn","x":"Bambus a baznu vždy rozštiep – celé môžu kvôli uväznenému vzduchu vybuchnúť."},{"t":"p","x":"**Umelé:** niektoré plasty (lyžička z MRE); drevo nasiaknuté voskom, olejom, repelentom; gáza z lekárničky napustená vazelínou."},{"t":"ok","x":"Rozštiepané drevo horí ľahšie, lebo je vnútri suchšie; ostré hrany ľahšie chytia. Roztriedené palivo sa ľahšie zapáli."}]},{"id":"2.10","title":"Palivo","web":false,"blocks":[{"t":"p","x":"Palivové drevo nemusí byť úplne suché – stabilne horiaci oheň ho vysuší. Kvôli dymu ho však chráň pred vlhkosťou."},{"t":"warn","x":"Do horiaceho ohňa nikdy nelej horľavú kvapalinu – aj od tlejúceho ohňa môže výbušne vzbĺknuť."},{"t":"li","items":["Suché štiepané tvrdé drevo (dub, hikória, jaseň): málo dymu, veľa tepla, ale ťažšie sa delí.","Borovica a ihličnany: horia rýchlo, veľmi dymia.","Trúchnivé drevo: málo tepla, skôr tlie a dymí.","Stojaci alebo šikmo vyvrátený suchý strom: vnútri býva suchý aj po daždi."]},{"t":"p","x":"**Odporúčané palivo:** stojace suché stromy a suché konáre, ktoré pri lámaní praskajú; vnútro padnutých stromov; v krajnom prípade zelené drevo jemne rozštiepané a zmiešané so suchým; v bezlesí zviazané zväzky suchej trávy, kaktus, suchý rašelinník, suchý trus, živočíšny tuk, piesok nasiaknutý olejom."}]},{"id":"2.11","title":"Príprava na zakladanie ohňa","web":false,"blocks":[{"t":"p","x":"Venuj príprave dosť času: zozbieraj všetky úrovne paliva a priprav zapaľovač **skôr**, ako zapáliš."},{"t":"ok","x":"Úspech = príprava + cvičenie + trpezlivosť."}]},{"id":"2.12","title":"Ohnisko","web":false,"blocks":[{"t":"p","x":"Miesto na oheň starostlivo vyčisti a dodrž bezpečnú vzdialenosť od prírodných (lístie, suchá tráva) aj umelých (batoh, stan) horľavín – vodorovne aj **zvislo** (šnúra na sušenie, nízke konáre)."},{"t":"warn","x":"Sila a smer vetra sa môžu meniť – iskry môžu prepáliť plachtu prístrešku alebo spôsobiť požiar."},{"t":"li","items":["Na udržanie ohňa: kovové ohnisko, jama vykopaná v zemi, kruh z kameňov."]},{"t":"warn","x":"Nekop ohnisko pri borovici: živičnaté korene ako knôty môžu aj o niekoľko dní spôsobiť lesný požiar."},{"t":"warn","x":"Mokré, pórovité alebo duté kamene môžu od tepla vybuchnúť – nepoužívaj kamene z brehu rieky."},{"t":"li","items":["V snehu treba vykopať až po zem – jama musí byť dosť široká a vzdušná, inak oheň uhasí topiaci sa sneh alebo nedostatok kyslíka.","Na mokrej, močaristej pôde treba plošinu (kamene, surové drevo)."]}]},{"id":"2.13","title":"Získaj čo najviac tepla","web":false,"blocks":[{"t":"p","x":"Použi **odrážač tepla** z kameňa, dreva alebo iného materiálu (izotermická fólia, plech), ktorý nasmeruje teplo do prístrešku. Polená/kamene okolo ohňa poslúžia ako podložka pre hrniec aj ako zábrana proti vetru."}]},{"id":"2.14","title":"Hospodárenie s palivom","web":false,"blocks":[{"t":"p","x":"Ulož a roztrieď ho podľa veľkosti (podpaľovač, triesky, drevo)."},{"t":"quote","x":"Pravidlo palca: nazbieraj trikrát viac podpaľovača a triesok, než sa zdá potrebné."},{"t":"ok","x":"Pri dlhšom pobyte rozumne hospodár a chráň prírodu – neplytvaj!"}]},{"id":"2.15","title":"Plošina pod oheň","web":false,"blocks":[{"t":"p","x":"Podložka je potrebná, ak by oheň roztopil hlboký sneh alebo ak je pôda mokrá či močaristá. Môže byť zo surových polien, kovu alebo nehorľavého materiálu."},{"t":"warn","x":"Na humusovej, rašelinovej pôde treba plošinu vždy: tlejúci rašelinový požiar sa takmer nedá uhasiť a môže horieť roky."}]},{"id":"2.16","title":"Prostriedky na zapálenie","web":false,"blocks":[{"t":"p","x":"Majú sa dať rýchlo a ľahko použiť aj v rukaviciach: zápalky (búrkové), zapaľovač, búrkový zapaľovač, horčíkový blok, ferocéričová tyčinka, kresadlo."},{"t":"ok","x":"Vždy maj aspoň 2–3 nezávislé zapaľovače uložené na rôznych miestach („dva sú jeden, jeden je žiadny“)."}]},{"id":"2.17","title":"Usporiadanie triesok","web":false,"blocks":[{"t":"p","x":"Malé množstvo triesok ulož do nízkeho kužeľa tak blízko, aby plamene preskočili. Nechaj malý otvor na zapálenie a prúdenie vzduchu. Najjednoduchším podpaľovačom je papier."}]},{"id":"2.18","title":"Použitie „perovej“ palice","web":false,"blocks":[{"t":"p","x":"Zápalky ušetríš „perovou“ palicou (feather stick) alebo vzdušným zväzkom tenkých suchých vetvičiek. Plameň chráň pred vetrom; sleduj smer vetra, aby plameň nechytil vlasy, odev, výstroj. Podpaľovač daj pod triesky na náveternú stranu."}]},{"id":"2.19","title":"Drobné drevo na podporu triesok","web":false,"blocks":[{"t":"p","x":"Pred zapálením alebo po ňom opatrne prikladaj na triesky drobné drevo, potom postupne väčšie. Drevo hrubé asi ako predlaktie ako podpera zabráni zaduseniu ohňa a zaistí prúdenie vzduchu."}]},{"id":"2.20","title":"Spôsoby zapálenia","web":false,"blocks":[{"t":"quote","x":"Výučba a použitie týchto spôsobov patria do výcviku úrovne „B“ a „C“ – tu ich uvádzame ako znalosti."},{"t":"p","x":"**Slnko (zväčšovacie sklo)** – treba silné, jasné slnko a dobrý podpaľovač: lupa (aj na buzole), okuliare, Fresnelova šošovka, zväčšovacie zrkadlo, reflektor baterky, vyleštené dno plechovky, krištáľovo čistá fľaša/pohár/vrecko s vodou."},{"t":"p","x":"**Elektrický prúd** – teplo skratu: tenký drôt, staniol zo žuvačky, oceľová vlna + batéria."},{"t":"warn","x":"Elektrické metódy sú nebezpečné úrazom a výbuchom, môžu spôsobiť smrteľný úraz elektrinou!"},{"t":"p","x":"**Trenie** – lukový vrták, ručný vrták, ohňový pluh, bambusová píla, ohňový valček."},{"t":"p","x":"**Iskra** – ferocéričová tyčinka; kresací kameň a oceľ (nôž, pilník)."}]},{"id":"2.21","title":"Ďalšie spôsoby","web":false,"blocks":[{"t":"p","x":"**Mini varič (na tuhý lieh):** kompaktný skladací oceľový varič s tabletami tuhého liehu. Jedna tableta má 10–15 g a horí asi 8–10 minút – na ohrev jedla bez otvoreného ohňa."},{"t":"p","x":"**Plastové predmety:** rúčku plastovej lyžičky zapichni zvisle do zeme a zapáľ hrot – horí asi 10 minút, dosť na vysušenie a zapálenie podpaľovača. Podobne šetrí zápalky sviečka."}]},{"id":"2.22","title":"Typy ohňov","web":false,"blocks":[{"t":"p","x":"Väčšina ohňov sa robí na konkrétnu potrebu (zohriatie, svetlo, varenie vody, varenie jedla). Názvy sa v literatúre líšia."},{"t":"li","items":["**Kužeľový (tee-pee):** dobrý zdroj svetla, sústredené teplo nad vrcholom, ideálny na varenie vody. Podpaľovač v strede, triesky šikmo okolo opornej palice, otvor na náveternej strane. Zapaľuj chrbtom k vetru.","**Zrub (log cabin):** rovnomerná, dlho horiaca žeravá vrstva, na varenie.","**Dlhý oheň (fínsky):** dve polená na sebe, horí celú noc, na zohriatie.","**Pyramídový (zapálený zhora):** treba ho málo prikladať.","**Hviezdicový (pastiersky):** polená sa posúvajú dovnútra, horí úsporne.","**Ležatý (lean-to):** chránený pred vetrom, triesky opreté šikmo.","**Indiánske ohnisko (Dakota fire hole):** dve prepojené jamy – málo svetla a dymu, horí dobre aj vo vetre, výhodné na maskovanie."]}]}]},{"id":"3","title":"Stavba prístreškov","sub":"I. časť, 3. lekcia","sections":[{"id":"3.1","title":"Úvod","web":false,"blocks":[{"t":"p","x":"Na úrovni SERE „A“ sa od každého vojaka očakáva, že v priateľskom prostredí v poľných podmienkach samostatne postaví z prideleného výstroja prístrešok, ktorý chráni pred škodlivými vplyvmi prírody. Samotný e-learning nestačí – treba cvičiť."}]},{"id":"3.2","title":"Prístrešok","web":false,"blocks":[{"t":"p","x":"Prístreškom môže byť čokoľvek, čo chráni pred nebezpečenstvami prostredia. Prostredie a situácia ovplyvňujú výber miesta a faktory, ktoré musí izolovaná osoba zvážiť."}]},{"id":"3.3","title":"Hľadiská prístrešku","web":false,"blocks":[{"t":"p","x":"Pri výbere miesta zváž:"},{"t":"li","items":["čas a energiu potrebnú na stavbu;","dĺžku pobytu (krátky alebo dlhší);","počasie (teplota, vietor, slnko, zrážky);","živé organizmy (ľudia, rastliny, zvieratá);","terén;","dennú dobu;","situáciu (nepriateľské, neutrálne prostredie)."]},{"t":"ok","x":"Čo najviac ochrany za čo najmenej energie!"}]},{"id":"3.4","title":"Úvahy – kontrolný zoznam","web":false,"blocks":[{"t":"li","items":["Je vôbec potrebný?","Mám dosť energie na stavbu?","Čo mám k dispozícii?","Na ako dlho ho staviam?","Je dostatočne chránený pred vplyvmi prostredia?","Treba ho maskovať?","Hrozia mu objektívne nebezpečenstvá?","Treba kúrenie?","Je zabezpečené vetranie?"]},{"t":"warn","x":"Na výber miesta prístrešku si vždy nechaj dosť času!"}]},{"id":"3.5","title":"Časový odhad","web":false,"blocks":[{"t":"p","x":"Nečakaj na poslednú chvíľu: v nepriaznivých podmienkach budeš odkázaný na zlý materiál a zlé miesto. Vedome stanov poradie medzi ohňom, vodou, jedlom a prístreškom."},{"t":"ok","x":"Pravidlo palca: so stavbou začni aspoň 1–2 hodiny pred zotmením."}]},{"id":"3.6","title":"Počasie a teplota","web":false,"blocks":[{"t":"p","x":"Ignorovanie počasia môže mať katastrofálne následky."},{"t":"li","items":["Na dne údolí je chladnejšie – **„jazero studeného vzduchu“**: v noci sem steká studený vzduch.","V chladných mesiacoch otvorené, slnečné miesto; v teple tienisté, kryté miesto.","V púšti je cez deň horúco a v noci mrzne – treba sa chrániť pred oboma."]}]},{"id":"3.7","title":"Vietor","web":false,"blocks":[{"t":"p","x":"V lete chladný vánok pomáha a odháňa hmyz (vrchol kopca, ostrov). Fúkajúci piesok, prach či sneh dráždi pokožku a oči, poškodzuje výstroj; pri ohni zvýš opatrnosť. V chlade treba ochranu pred vetrom a záveje."}]},{"id":"3.8","title":"Zrážky","web":false,"blocks":[{"t":"warn","x":"Nestavaj vo výmole, odvodňovacom žľabe ani vyschnutom koryte – náhla povodeň, bahnotok, prívalová vlna."},{"t":"warn","x":"V zasnežených horách sa vyhni lavínovým svahom."}]},{"id":"3.9","title":"Živé organizmy","web":false,"blocks":[{"t":"p","x":"Zváž všetky formy života. Ľudia môžu byť nepriateľ alebo iná skupina, pred ktorou musíš zostať nevidený."},{"t":"li","items":["**Hmyz:** na kopci, hrebeni, vo vetre je ho menej. Vyhni sa stojatej vode (komáre, včely, osy) a mravenisku.","**Zvieratá:** nestavaj pri zvieracích chodníkoch, brlohoch, napájadlách.","**Nebezpečné rastliny:** tŕne, popínavé rastliny, jedovaté rastliny. Vyhni sa odumretým, napoly vyvráteným stromom a konárom – **„vdovári“** môžu vo vetre či daždi spadnúť a zabiť.","Pri ohni ľahko vzbĺkne opadané lístie a hustá suchá vegetácia."]}]},{"id":"3.10","title":"Terén","web":false,"blocks":[{"t":"warn","x":"Vyhni sa lavínovým, skalným a zosuvným oblastiam – poznáš ich podľa pruhu odlišnej vegetácie od vrcholu kopca po úpätie."},{"t":"warn","x":"Skalné výklenky a previsy pred použitím skontroluj."}]},{"id":"3.11","title":"Požiadavky a zásady plánovania","web":false,"blocks":[{"t":"p","x":"Dobrý prístrešok poskytuje telesnú aj duševnú pohodu na odpočinok, ktorý je nevyhnutný pre dobré rozhodnutia – čím dlhšie sa záchrana odkladá, tým je to kritickejšie."},{"t":"li","items":["Má stačiť s málo prácou a energiou; neobmedzuj sa na vopred určený tvar.","Využi prírodný úkryt (skalný previs, výklenok, jaskyňa, puklina, padnutý kmeň, koreňová stena, snežná stena) a doplň ho.","Izoláciu zvýšiš vegetáciou či padákom; odrážač tepla postav pod skalným previsom alebo pred jaskyňou."]}]},{"id":"3.12","title":"Určenie účelu prístrešku","web":false,"blocks":[{"t":"p","x":"Typ ovplyvňuje: podnebie; počasie; hmyz; dostupnosť materiálu; dĺžka pobytu; prítomnosť, počet a výzbroj nepriateľa; fyzická kondícia izolovanej osoby."},{"t":"warn","x":"Na nepriateľskom území mysli na stopy už pri stavbe a rozoberaní: minimálny zásah, dôkladné odstránenie."}]},{"id":"3.13","title":"Parametre prístrešku","web":false,"blocks":[{"t":"li","items":["Dosť veľký na pohodlie, ale nie taký, aby dal veľa práce (v chlade menší = teplejší).","Ak zakladáš oheň, zabezpeč odvod dymu a oxidu uhoľnatého – aj keď oheň nedymí (tuhý lieh, plyn, dezinfekčný gél).","Oheň len mimo prístrešku; otvor v uhle **90°** k prevládajúcemu vetru."]},{"t":"ok","x":"Ideálna vzdialenosť ohňa od prístrešku: asi **90–100 cm**."},{"t":"warn","x":"Pri vraku lietadla či vozidla nezakladaj oheň (vytečené palivo). Radšej prenes materiál do bezpečnej vzdialenosti."}]},{"id":"3.14","title":"Ochrana pred dažďom a snehom","web":false,"blocks":[{"t":"p","x":"Pri pórovitom (nepremokavom) materiáli platí zásada **„sklon a napnutie“**: sklon **45–60°**, materiál napnutý a bez záhybov. Nedotýkaj sa materiálu, keď po ňom tečie voda – tam to zatečie."}]},{"id":"3.15","title":"Materiál, miesto, kostra","web":false,"blocks":[{"t":"p","x":"**Zber materiálu:** kostra, krytina, lôžko/izolácia, upevňovacie prostriedky – pred stavbou maj všetko poruke."},{"t":"ol","items":["Z tyčí drevenej kostry odstráň všetky ostré hrany a pahýle.","Pri prírodnom prístrešku nechaj konáre na vonkajšej strane stromu – sú dobrou nosnou konštrukciou.","Na kostru a krytinu: kôra, odrezané konáre, palmové listy, tráva, prepletená vegetácia.","Pri padáku odstráň šnúry a nastrihaj na mieru."]},{"t":"p","x":"**Príprava miesta:** odstráň kamene a vetvičky z lôžka, zrež prečnievajúcu vegetáciu."},{"t":"p","x":"**Kostra:** unesie sneh, zrážky a nárazy vetra. Optimálny je sklon **60°**. Pri padáku napni stredový šev, pracuj zozadu dopredu, ťahaj v 90° k záhybom. Pri prírodnej krytine použi **šindľovú metódu**: zdola nahor, s prekrytím – zvnútra nesmie byť vidno von."}]},{"id":"3.16","title":"Typy prístreškov","web":false,"blocks":[{"t":"p","x":"**Podľa materiálu:** prírodný, umelý, kombinovaný."},{"t":"p","x":"**Podľa maskovania:** nápadný alebo skrytý."},{"t":"p","x":"**Podľa vyhotovenia:** existujúci, narýchlo zhotovený, improvizovaný."},{"t":"p","x":"Klimatické pásma: horúce (rovníkové, tropické, púštne, savana, monzún), mierne (oceánske, stredomorské, kontinentálne), studené (subarktické) a horské."}]},{"id":"3.17","title":"Požiadavky na skrytý prístrešok","web":false,"blocks":[{"t":"li","items":["Blízko vody, jedla, paliva, signálneho miesta alebo miesta vyzdvihnutia.","Bezpečný, chráni pred nebezpečenstvami prostredia; dosť materiálu nablízku.","Dosť veľký na sedenie, ležanie a uloženie výstroja; rovné dno.","Ťažko prístupný, na najmenej nápadnom mieste.","Viac prístupových a únikových ciest; možnosť okamžite odísť.","Prírodné maskovanie (aj proti leteckému prieskumu); nepravidelný tvar, splývajúca farba.","Ľahko rozobrateľný (ľahko rozviazateľné uzly)."]},{"t":"p","x":"**Nápadný (nemaskovaný) prístrešok:** ľahko prístupný, na viditeľnom mieste, označený pestrou farbou a svetlom."}]},{"id":"3.18","title":"Existujúci, narýchlo zhotovený, improvizovaný","web":false,"blocks":[{"t":"li","items":["**Existujúci:** rímsy, padnuté kmene, jaskyne, priehlbiny pri stromoch; v meste budovy. Ak existuje, použi ho – nový stavaj len v prípade potreby.","**Narýchlo zhotovený:** rýchlo, s minimálnou námahou: záchranný čln, diely vozidla či lietadla, padák.","**Improvizovaný:** rýchlo postaviteľný a rozobrateľný (pultový, diamantový, sedlový, tieniaci, tee-pee) – len ak netreba okamžite ujsť."]}]},{"id":"3.19","title":"Prístrešky miernej zóny","web":false,"blocks":[{"t":"ol","items":["**Jaskyňa** – dobre sa vykuruje, bez ohňa je studená; nápadné miesto zakreslené v mapách; bez únikovej cesty; dravce.","**Skalný výklenok, previs** – tienistý, prievanový, chráni pred zrážkami; ťažko prístupný, bez únikovej cesty.","**Prístrešok z drnov** – drny hrubé asi 5 cm na pevnej kostre; dá sa vykúriť, v lete chladný, odolný voči vode a hmyzu, ohňovzdorný. Treba rýľ; náročný na čas, materiál a energiu – len na dlhodobý pobyt.","**Listový (sedlový) prístrešok** – v listnatom lese, výborne sa maskuje; veľa materiálu a času; hmyz; kúrenie ohňom je riskantné.","**Padnutý strom, doplnený** – over stabilitu stromu; dobre sa maskuje, pred vetrom a zrážkami chráni obmedzene."]}]},{"id":"3.20","title":"Prístrešky z plachty","web":false,"blocks":[{"t":"p","x":"Osobný výstroj vojaka typu plachta: celta, pončo, padák, plachta 2–3×3 m, izotermická fólia, vrece na odpad."},{"t":"ol","items":["**Pultový (šikmý)** – najrýchlejší, dobre chráni pred dažďom, sneh neudrží; pred vetrom chránený z jednej strany; oheň zohreje veľkú plochu. Pri sklone 60°+ zvedie vodu aj nepremokavý materiál.","**Upravený pultový so stieškou** – zo sedlového zdvihnutím jednej strany; viac šnúr; dbaj na vzdialenosť ohňa.","**Pultový s podlahou** – zahnutá časť plachty izoluje od vlhkosti zeme.","**Diamantový** – stačí jeden kotviaci bod; pred vetrom chráni v 180°; dobre sa vykuruje.","**Sedlový (typ A)** – výborne chráni pred dažďom, pred vetrom z dvoch strán, ťažko sa vykuruje.","**Upravený sedlový** – uzavretá zadná časť, chránený z viacerých strán.","**Zdvihnutý sedlový** – horúce pásmo (džungľa); vzdušný, pred vetrom nechráni.","**Tee-pee (padák)** – výborne chráni pred vetrom, dažďom, chladom a hmyzom, vnútri môže byť oheň; na skrytý prístrešok je priveľký, ale v noci sa hodí na signalizáciu.","**Tee-pee (celty) – „búda“** – dve zapnuté celty; dôležitá je stabilita stredovej tyče; bez napnutia zateká.","**Brloh (bivak)** – suchá izolácia v nepremokavom obale, „rob ako zvieratá“; zohreje sa telesným teplom.","**Vraky vozidiel** – krídlo, chvost, trup na tieň; vnútri sa v horúčave prehrieva, v mraze chladne; nebezpečenstvo požiaru!","**Budovy, ruiny** – opustené budovy, kôlne, garáže, kanály; neskrývaj sa na jedinom nápadnom mieste; ak sa dá, miesta striedaj."]}]},{"id":"3.21","title":"Prístrešky horúcej zóny","web":false,"blocks":[{"t":"p","x":"**Trópy, džungľa:** na kopcoch, vyvýšených miestach, ďalej od močiarov; priamo na zemi sa stavať dá len málokde."},{"t":"ol","items":["**Zdvihnuté drevené lôžko** – na mokrú, močaristú pôdu; náročné na čas, náradie a materiál.","**Hojdacia sieť** – z plachty či padáka medzi dvoma nosnými bodmi; rýchlo sa zbalí, zanecháva málo stôp; v chlade sa ťažko izoluje."]},{"t":"p","x":"**Púšť:** stavaj skoro ráno, večer alebo v noci. Tieň skál, dún; materiál 30–40 cm nad tebou."},{"t":"ol","items":["**Improvizovaný tienidlo** – 2–3 vrstvy so vzduchovou medzerou 30–40 cm; lôžko asi 40 cm nad povrchom alebo pod ním."]}]},{"id":"3.22","title":"Sneh a ľad – zásady","web":false,"blocks":[{"t":"p","x":"V malom, dobre postavenom snežnom prístrešku teplota zriedka klesne pod –10 °C. Telesné teplo ju zvýši asi o 4 °C, jedna sviečka o ďalšie asi 4 °C."},{"t":"ok","x":"Ak nevidieť tvoj dych, vnútri je priteplo – schlaď, inak sa bude topiť a kvapkať."},{"t":"li","items":["Tri úrovne: hore oheň/vetranie, v strede lôžko, dole jazero studeného vzduchu.","Zľadovatenú vnútornú vrstvu oškrab.","Starý prístrešok si nechaj, kým nedokončíš nový."]},{"t":"warn","x":"Pri fyzickej práci telo vyrába až 1500 W tepla – pred stavbou vyzleč vrstvy, otvor zipsy. **Pot je v chlade smrteľne nebezpečný!** Pracuj pomaly, rovnomerným tempom."}]},{"id":"3.23","title":"Vchod, vetranie, hygiena","web":false,"blocks":[{"t":"li","items":["Otvor v 90° k prevládajúcemu vetru; vchod zatarasi snežným blokom, batohom.","Na noc si vezmi lopatu dnu – ak ťa zasype sneh, vykopeš sa."]},{"t":"warn","x":"Sviečky, horáky a petrolejové lampy tvoria oxid uhoľnatý: vetracie otvory musia byť na streche aj pri vchode."},{"t":"li","items":["Hygiena: ak sa dá, zostaň vnútri; v samostatnej chodbe WC; fľaše, snežné bloky."]}]},{"id":"3.24","title":"Holé a zalesnené oblasti","web":false,"blocks":[{"t":"p","x":"**Holé:** morské pobrežie, ľadovec, nad hranicou lesa; málo materiálu. Stavaj na záveternej strane hrebeňov naviatych vetrom. Vyhni sa nestabilnému ľadu."},{"t":"ol","items":["**Snežná jaskyňa** – treba lopatu; rýchla, výborná ochrana pred vetrom; vetranie; lavínové riziko.","**Quinzee** (udupaný snežný kopec) – časovo náročný, veľa energie; odev premokne, hneď ho vysuš.","**Iglu** – treba rezací nástroj a pevný sneh; veľa času a presnosti."]},{"t":"p","x":"**Zalesnené:** dosť materiálu; nie na brehu rieky (povodeň, bahnotok)."},{"t":"ol","items":["**Snežná jama pri strome** – dutina pod nízkymi konármi smreka; kop zo záveternej strany; nezraz sneh z konárov.","**Snežný zákop** – aspoň 1–1,5 m snehu; kopací nástroj; s plachtou rýchly a nenáročný; prikrytý čečinou a snehom izoluje a maskuje."]}]},{"id":"3.25","title":"Údržba a vylepšenia","web":false,"blocks":[{"t":"p","x":"Pri dlhšom používaní ho udržiavaj: napnutá plachta lepšie chráni; dvere proti vetru a hmyzu; odrážač tepla, predsieň, pracovný priestor, samostatné uloženie výstroja a paliva."}]},{"id":"3.26","title":"Spánkový systém – spacák","web":false,"blocks":[{"t":"p","x":"Spacák dáva najviac tepla, len keď je čistý, suchý a natrasený. Prevráť ho naruby, vytras ho, vysuš na slnku alebo v bezpečnej vzdialenosti od ohňa."},{"t":"warn","x":"Nedýchaj do spacáka (nos a ústa von) – dych ho navlhčí. Fľašu v ňom nenechávaj."},{"t":"ok","x":"Pred uložením: ľahký pohyb (bez potenia), jedlo a teplý nápoj."},{"t":"p","x":"**Improvizovaný spacák:** padák, plachta, deka preložená pozdĺžne, dole a na boku zošitá či zviazaná, o 15–25 cm dlhšia ako tvoja výška. Pri dvojitej vrstve vyplň medzeru suchou trávou, slamou, kartónom, novinami, penou."}]},{"id":"3.27","title":"Podložka – izolácia od zeme","web":false,"blocks":[{"t":"p","x":"Izolácia treba aj smerom k zemi: prírodná (suché lístie, čečina, trstina) alebo umelá (karimatka, nafukovačka). Izoluje vzduchová vrstva – nesmie sa stlačiť."},{"t":"warn","x":"Aj v zimnom spacáku s komfortom –25 °C bude zima už pri 0 °C, ak chýba izolácia od zeme. Podchladenie môže nastať už pod 15 °C!"},{"t":"li","items":["**Hodnota R:** izolačná schopnosť karimatky – čím vyššia, tým lepšie. Asi 1,0 (minimálna) až 5+ (výborná, zimná).","Každé kilo navyše sa na pochode počíta."]},{"t":"p","x":"**Umelé:** spacák, deka, pončo, celta, plachta 3×3 m, padák, izotermická fólia, vrece na odpad, karimatka, nafukovačka."},{"t":"p","x":"**Prírodné:** suchá tráva, lístie, zväzky trstiny, balík slamy, čečina, drevený rám vystlaný prírodným materiálom."},{"t":"p","x":"**Doplnky:** stanové kolíky, drevené kolíky, 4–5 m lana 5–6 mm, 5–6 m paracordu."}]},{"id":"3.28","title":"Uzly","web":false,"blocks":[{"t":"warn","x":"Niektoré uzly sa používajú aj pri lezení a výškových prácach, tam však platia iné pravidlá. Nesprávne použitie je nebezpečné a môže zabiť!"},{"t":"li","items":["**Jednoduchý uzol (overhand)** – upevnenie, úchytný uzol, koniec lana. + Rýchly, základ ďalších uzlov. − Ťažko sa rozväzuje, môže skĺznuť. ⏱ 10 s.","**Jednoduchá kĺzavá slučka (slip knot)** – bežný uzol. Upevnenie. + Rýchlo sa viaže aj rozväzuje. − Menej bezpečný. ⏱ 15 s.","**Jednoduchá slučka (overhand loop)** – pevná slučka na lane; úchyt, závesný bod, napínacie oko. + Dá sa uviazať, aj keď ani jeden koniec nie je voľný. − Po zaťažení takmer nerozviazateľná. ⏱ 15 s.","**Polovičný uzol** – zväzovanie zväzkov a balíkov. + Ľahko sa rozväzuje. − Neistý. ⏱ 20 s."]}]}]},{"id":"4","title":"Získavanie a úprava vody","sub":"I. časť, 4. lekcia","sections":[{"id":"4.1","title":"Úvod","web":false,"blocks":[{"t":"p","x":"Voda je jedným z najdôležitejších prvkov udržania ľudského života. Organizmus tvorí asi z **70 %** voda; je nevyhnutná pre krvný obeh, činnosť obličiek, dýchanie, trávenie a reguláciu teploty."},{"t":"quote","x":"Bez jedla prežiješ aj týždne, bez vody v priemere len **3 dni**."},{"t":"p","x":"V situácii prežitia nie je pitná voda zaručená – každý vojak musí poznať spôsoby jej získania, úpravy a bezpečného skladovania. Nedostatok vody spôsobuje dehydratáciu, zmätenosť, svalovú slabosť a napokon smrť."}]},{"id":"4.2","title":"Dehydratácia","web":false,"blocks":[{"t":"p","x":"Strata tekutín spojená aj so stratou elektrolytov. Tri hlavné typy:"},{"t":"ol","items":["**Izotonická:** voda a elektrolyty sa strácajú v rovnakom pomere. Príčina: hnačka, vracanie, popáleniny, potenie. Príznaky: únava, začervenaná pokožka, bolesť hlavy, tmavý moč, kŕče. Liečba: izotonické doplnenie tekutín.","**Hypotonická:** nedostatok elektrolytov pri doplňovaní vody bez minerálov. Nedostatok sodíka → porucha vedenia vzruchov, svalové kŕče. Príznaky: slabosť, nevoľnosť, opuchy. Liečba: doplnenie solí a elektrolytov, obmedzenie vody.","**Hypertonická:** nedostatok tekutín – plazma hustne a odoberá vodu z buniek. Príznaky: silný smäd, suché sliznice, zmätenosť. Liečba: postupné, pomalé doplňovanie vody."]},{"t":"ok","x":"Sleduj moč: svetlo slamovožltý = v poriadku; tmavý a málo = pi!"}]},{"id":"4.3","title":"Elektrolyty","web":false,"blocks":[{"t":"p","x":"Minerály, ktoré sa vo vode rozkladajú na ióny – kľúčové pre činnosť buniek a nervovosvalový prenos. Pri veľkej záťaži, extrémnych teplotách a nedostatku vody je ich rovnováha životne dôležitá."},{"t":"li","items":["**Sodík (Na⁺):** krvný tlak, objem krvi, činnosť svalov a nervov; potením sa rýchlo stráca. Zdroj: soľ, slané jedlo, elektrolytové roztoky.","**Draslík (K⁺):** srdcový rytmus, činnosť svalov. Zdroj: banán, sušené ovocie, poľná dávka.","**Vápnik (Ca²⁺):** sťah svalov, kosti, zrážanie krvi. Zdroj: sušené mlieko, konzervy, doplnky.","**Horčík (Mg²⁺):** nervovosvalová činnosť, prevencia kŕčov. Zdroj: semená, obilniny.","**Chlorid (Cl⁻):** acidobázická rovnováha, trávenie. Zdroj: kuchynská soľ.","**Bikarbonát (HCO₃⁻):** pH krvi. Tvorí ho telo, dá sa doplniť roztokmi."]},{"t":"p","x":"**Príčiny straty:** silné potenie (horúčava, ťažký výstroj), hnačka, vracanie (kontaminovaná voda), zranenia, popáleniny, dlhotrvajúci nedostatok vody."},{"t":"p","x":"**Príznaky nedostatku:** svalové kŕče, slabosť, závrat; poruchy srdcového rytmu, nízky tlak; poruchy sústredenia; v ťažkých prípadoch strata vedomia."}]},{"id":"4.4","title":"Doplňovanie elektrolytov","web":false,"blocks":[{"t":"li","items":["Vodu a elektrolyty dopĺňaj **spolu** – pitie len vody pri potení môže spôsobiť hyponatriémiu.","Izotonické prášky v balíčkoch MRE sa rýchlo vstrebávajú.","Soľné tablety: v extrémnej horúčave, v púšti.","Núdzový roztok: **½ čajovej lyžičky soli / 1 liter vody**.","Sušené ovocie, oriešky, sušené mäso, energetické tyčinky – draslík, horčík."]},{"t":"p","x":"**Povinné položky vojenskej súpravy na prežitie:** elektrolytový nápojový prášok, soľné tablety, tablety na úpravu vody, kompaktný čistič vody."}]},{"id":"4.5","title":"Otrava vodou (hyponatriémia)","web":false,"blocks":[{"t":"p","x":"Život ohrozujúci stav: za krátky čas priveľa vody a hladina sodíka v krvi klesne – bunky (aj mozgové) napučia, hrozí opuch mozgu až smrť."},{"t":"p","x":"**Príčiny:** obličky vylúčia najviac asi 0,8–1,0 l/hod; extrémna záťaž s nadmernou hydratáciou; chýbajúce elektrolyty; stres, nutkavé pitie."},{"t":"p","x":"**Prevencia:**"},{"t":"li","items":["S mierou: najviac **0,5–0,8 litra/hod**, rovnomerne rozložene.","Elektrolyty dopĺňaj v horúčave a pri dlhom nasadení.","Riaď sa smädom – nepi nutkavo „do zásoby“, ale pi pravidelne."]},{"t":"warn","x":"Voda je strategický zdroj: škodí plytvanie aj nadmerné pitie."}]},{"id":"4.6","title":"Zahustenie krvi","web":false,"blocks":[{"t":"p","x":"Hemokoncentrácia nezávisí len od príjmu vody, ale aj od straty tekutín a rovnováhy elektrolytov."},{"t":"p","x":"**Príčiny:** veľká strata tekutín (pot, dych, moč, hnačka); horúčava + záťaž bez doplnenia soli a vody; ťažká dehydratácia (riziko trombózy); priveľa soli či bielkovín."},{"t":"p","x":"**Správna rovnováha:** voda + elektrolyty spolu; pri záťaži 0,5–0,8 l/hod, v horúčave soľné tablety alebo elektrolytový prášok."}]},{"id":"4.7","title":"Hľadanie zdrojov vody","web":true,"blocks":[{"t":"p","x":"Najprv hľadaj vždy najčistejší zdroj: **prameň > tečúca voda > stojatá voda**."},{"t":"li","items":["Vodu prezrádza dno údolí, zelená vegetácia pod skalami, trstina, ostrica, vŕba, jelša.","Zvieracie chodníky dolu svahom často vedú k vode; roje hmyzu, vtáky na úsvite a za súmraku.","Na vonkajšom oblúku vyschnutého koryta môžeš vykopať priesakovú vodu.","Dažďová voda: zachytená na plachte či ponču – najčistejší prírodný zdroj.","**Rosa:** na úsvite ju zotri z trávy handrou a vyžmýkaj.","Sneh a ľad: **roztop, nejedz!** – ochladzuje telo a vysušuje ústa. Ľad dá viac vody za menej paliva.","**Transpiračné vrecko:** priehľadné vrecko na živej olistenej vetve na slnku – za pár hodín sa nazbiera kondenzát.","**Slnečná destilácia:** jama, v strede nádoba, nad ňou fólia zaťažená kameňom v strede."]},{"t":"warn","x":"Nikdy nepi morskú vodu, moč, alkohol – zhoršujú dehydratáciu."},{"t":"warn","x":"Vyhni sa vode pri uhynutých zvieratách, odpade, priemysle, poliach, vode penivej, mastnej, zapáchajúcej alebo bez života."}]},{"id":"4.8","title":"Filtrovanie a čírenie","web":true,"blocks":[{"t":"p","x":"Filtrovanie odstráni zákal, ale **nedezinfikuje** – potom vždy treba vodu upraviť."},{"t":"ol","items":["Usadzovanie: nechaj stáť, potom opatrne odlej vrch.","Improvizovaný filter (fľaša, ponožka, nohavica), vrstvy zhora nadol: tráva/látka → jemný piesok → drevené uhlie (z ohňa, nie popol) → štrk.","Preliatie cez látku (šatka, tričko) – proti väčším nečistotám."]},{"t":"ok","x":"Drevené uhlie zníži pach a chuť, ale nezabije choroboplodné zárodky."}]},{"id":"4.9","title":"Úprava vody","web":true,"blocks":[{"t":"ol","items":["**Varenie – najistejšie:** prudký var aspoň **1 minútu**; nad 2000 m **3 minúty**. Nechaj vychladnúť prikryté.","**Tablety s oxidom chloričitým** (napr. Micropur): proti baktériám, vírusom aj kryptosporídiám. Asi 30 minút; pri studenej alebo kalnej vode až **4 hodiny**.","**Jódové tablety / jódová tinktúra:** asi 30 minút; v studenej vode dlhšie. Nie v tehotenstve, pri ochorení štítnej žľazy ani dlhodobo.","**Chlórové bielidlo (bez vône, 5–6 %):** 2 kvapky/liter čírej, 4 kvapky/liter kalnej vody, 30 minút; má zostať jemná vôňa chlóru.","**Filtračná fľaša, mikrofilter:** proti baktériám, prvokom; proti vírusom len v kombinácii s chémiou.","**UV (SODIS):** priehľadná PET fľaša celý deň na prudkom slnku – len v krajnom prípade."]},{"t":"warn","x":"Po úprave tabletou uvoľni uzáver a fľašu otoč, aby sa vydezinfikoval aj závit."},{"t":"warn","x":"Prášok s vitamínom C pridaj až po uplynutí času úpravy – znižuje účinok."}]},{"id":"4.10","title":"Skladovanie a hospodárenie","web":true,"blocks":[{"t":"li","items":["V čistej, uzatvárateľnej, označenej nádobe, v tieni; upravenú a neupravenú vodu nikdy nemiešaj.","Nešetri do poslednej kvapky: voda je lepšie v tele ako vo fľaši – ale hospodár s ňou.","Znižuj stratu vody: v najteplejších hodinách odpočívaj v tieni, pohybuj sa v noci, nefajči, málo hovor, dýchaj nosom."]}]}]},{"id":"5","title":"Únik (Evasion)","sub":"II. časť, 1. lekcia — podľa osnovy učiva, doplnené z verejných zdrojov","sections":[{"id":"5.1","title":"Cieľ úniku","web":true,"blocks":[{"t":"p","x":"Únik je súbor postupov, ktorými sa izolovaná osoba vyhne odhaleniu a kontaktu s nepriateľskými či potenciálne nepriateľskými silami a vráti sa k vlastným alebo bude vyzdvihnutá."},{"t":"ok","x":"Zajatie je horšie ako únik! Každé rozhodnutie smeruje k tomu, aby si zostal nevidený a vrátil sa."},{"t":"li","items":["Prvý krok po izolovaní: okamžite opusť miesto dopadu/nehody – tam hľadajú najprv.","Vezmi len potrebný výstroj, zvyšok ukry alebo zničí.","Presuň sa do úkrytu, potom S-T-O-P: zastav, premýšľaj, pozoruj, plánuj."]}]},{"id":"5.2","title":"Skrývanie a alternatívne ciele","web":true,"blocks":[{"t":"li","items":["Úkryt vyberaj podľa zásady **„LOW“**: nízka silueta (Low), nepravidelný tvar (Odd), splývajúci s terénom (Wild) – nie najočividnejší ker či budova.","Hlavný cieľ: určené miesto vyzdvihnutia / vlastné sily. Alternatívy: záložný bod vyzdvihnutia, neutrálne územie, hranica, spojenecké sily.","Vždy maj plán B: únikovú cestu, zhromaždisko."]}]},{"id":"5.3","title":"Maskovanie","web":false,"blocks":[{"t":"p","x":"Cieľom maskovania je, aby izolovaná osoba, jej výstroj a prístrešok neboli rozpoznateľné zmyslami a prostriedkami nepriateľa. Maskovanie je aktívna činnosť – treba ho neustále udržiavať."}]},{"id":"5.4","title":"Druhy pozorovania","web":true,"blocks":[{"t":"p","x":"**Päť zmyslov:** nepriateľ vidí, počuje, cíti (tabak, mydlo, varenie, oheň), hmatá (stopy) a ochutná – chráň sa pred všetkými."},{"t":"p","x":"**Priame pozorovanie:**"},{"t":"li","items":["Fyzické stopy: odtlačky nôh, zlomené konáre, pošliapaná tráva, odhodené odpadky, stopy ohňa.","Miestni obyvatelia: psy, pastieri, poľovníci, roľníci – sú najlepšími „senzormi“."]},{"t":"p","x":"**Nepriame pozorovanie:** letecký a dronový prieskum („pohľad zhora“ – pravidelné tvary, tiene a chodníky vyniknú), termovízia a nočné videnie, rádiové zameriavanie."}]},{"id":"5.5","title":"Faktory rozpoznania","web":true,"blocks":[{"t":"p","x":"Čo ľudské oko okamžite zachytí – to treba odstrániť:"},{"t":"ol","items":["**Pohyb** – najviac prezrádza; pohybuj sa pomaly a rozvážne, pri pozorovaní znehybni.","**Poloha** – nie na horizonte, nie na vyvýšenom bode, nie na očividnom mieste.","**Tvar** – rozbi obrys človeka, prilby a zbrane.","**Tieň** – vlastný tieň ťa prezradí; využi hlboké tiene prírody.","**Textúra** – hladký povrch je svetlejší a lesklý; drsný tmavší.","**Farba** – škvrnité sfarbenie zodpovedajúce okoliu.","**Tón** – rozdiely jasu; svietiaca škvrna tváre a rúk.","**Lesk** – hodinky, okuliare, kov, optika, spotená pokožka – zakry, matný povrch."]},{"t":"ok","x":"Pomôcka: **pohyb – tvar – tieň – lesk – silueta – rozostupy**."}]},{"id":"5.6","title":"Zásady maskovania","web":true,"blocks":[{"t":"li","items":["**Miesto:** zapadá do okolia, nenápadné, s viacerými východmi.","**Maskovacia disciplína:** nezanechávaj stopy ani odpadky; vyhýbaj sa chodníkom.","**Svetelná disciplína:** v noci žiadne svetlo (baterka, zápalka, displej, cigareta) – je vidieť zďaleka.","**Proti nočnému videniu a termovízii:** skry telesné teplo za zeminu, skaly, hustú vegetáciu či izotermickú fóliu (správne použitú); nie v otvorenom teréne.","**Zvuková disciplína:** upevni výstroj, šepkaj, posunky, nelám konáre.","**Skrytý prístrešok:** nepravidelný tvar, miestny materiál, skrytý aj pred pohľadom zhora."]}]},{"id":"5.7","title":"Maskovanie jednotlivca","web":true,"blocks":[{"t":"li","items":["**Tvar:** rozbi obrys miestnou vegetáciou (na odeve, prilbe, batohu); s meniacim sa okolím ju vymieňaj.","**Pozadie:** vždy sa prispôsob pozadiu – tmavý odev sa na svetlom pozadí vykreslí.","**Techniky:** farba na tvár: vystúpené časti (čelo, nos, lícne kosti, brada) tmavšou, priehlbiny svetlejšou farbou; aj ruky a krk.","**Splynutie:** pred pohybom skontroluj, ako zapadáš do okolia; pomalý, nepravidelný pohyb."]}]},{"id":"5.8","title":"Skrývanie v miernom pásme","web":true,"blocks":[{"t":"li","items":["Na odeve: čerstvá miestna vegetácia – nie jeden druh, nie priveľa.","Prírodné materiály: blato, zemina, uhlie na tvár; lístie, mach.","Pri prístrešku: nepravidelný tvar, miestny materiál, žiadne rovné hrany; zakrytý aj zhora.","**Oheň počas skrývania:** len ak je nevyhnutný; malý bezdymový oheň (suché tvrdé drevo), indiánske ohnisko, pod korunami; cez deň prezrádza dym, v noci svetlo."]}]},{"id":"5.9","title":"Zháňanie jedla počas úniku","web":true,"blocks":[{"t":"li","items":["Prednosť má skrývanie – zháňanie jedla je riziko.","Zvieratá: pasce, slučky (tiché, pasívne); lov či streľba robí hluk – len v krajnom prípade.","Rastliny: len druhy, o ktorých isto vieš, že sú jedlé; v pochybnostiach nejedz.","V obývanej oblasti: neber nič, čo by niekomu chýbalo; opustená záhrada, sad – opatrne.","Príprava: surové živočíšne jedlo a vodu uprav a uvar."]}]},{"id":"5.10","title":"Bezpečnosť a pohyb","web":true,"blocks":[{"t":"p","x":"**Opatrenia:** pravidelne zastav, pozeraj, počúvaj, čuchaj (STOP–LOOK–LISTEN–SMELL). Pred pohybom si naplánuj trasu a ďalší úkryt."},{"t":"p","x":"**Pozorovanie terénu:** aj bez ďalekohľadu: po sektoroch, od blízka do diaľky; sleduj horizont a tiene."},{"t":"p","x":"**Hlavné príčiny zajatia:** riskovanie z netrpezlivosti, únavy, hladu či smädu; používanie ciest, mostov, dedín; stopy; žiadosť o pomoc od nespoľahlivej osoby."},{"t":"p","x":"**Pohyb:**"},{"t":"li","items":["Využívaj zlé svetelné podmienky (úsvit, súmrak, noc).","Trasa: vyhni sa cestám, chodníkom, hrebeňom a otvorenému terénu; choď pod hrebeňom, priehlbinami, okrajom porastu.","Zakrývanie stôp: tvrdý povrch, kamene, okraj vody; stúpaj do už pošliapaných miest.","Zníženie rizika odhalenia: krátke úseky, časté zastávky, zmeny smeru."]},{"t":"p","x":"**Spôsoby pohybu:** plíživá chôdza, beh (len ak ťa odhalili), plazenie (nízke, vysoké, bočné)."}]},{"id":"5.11","title":"Zhromaždiská (Rally Points)","web":true,"blocks":[{"t":"p","x":"Vopred určený, ľahko rozpoznateľný bod v teréne, kde sa skupina po rozptýlení znovu zhromaždí."},{"t":"li","items":["Rozpoznateľný, ale nie nápadný; s určeným časom čakania a plánom ďalšieho postupu.","Na zhromaždisku: zabezpečenie, kontrola počtu, ošetrenie ranených, zhodnotenie, plán.","Prekážky: rieky, cesty, ploty, obce, mínové polia – prekonávaj ich len odôvodnene a po prieskume."]}]},{"id":"5.12","title":"Pomôcky na únik","web":true,"blocks":[{"t":"li","items":["**Osobná súprava na prežitie (PSK):** zapaľovač, úprava vody, signalizačné prostriedky, buzola, nôž, šnúra, prvá pomoc, jedlo, mapa – vždy na tele.","**Mapy a tabuľky:** úniková mapa (s blood chit), kódové tabuľky.","**Dvojjazyčná ukazovacia karta („Pointee-Talkee“):** obrázkovo-textový hárok v miestnom jazyku na komunikáciu ukazovaním.","**Asistovaný únik:** organizovaná, preverená sieť pomocníkov.","**Nečakaná pomoc:** miestny pomocník – veľké riziko, len odôvodnene.","**Kontakt s miestnymi:** len v krajnom prípade, s osobou, ktorá je sama, po pozorovaní; neprezraď viac, ako je nutné."]}]}]},{"id":"6","title":"Topografia","sub":"II. časť, 2. lekcia — podľa osnovy učiva, doplnené z verejných zdrojov","sections":[{"id":"6.1","title":"Úvod","web":true,"blocks":[{"t":"p","x":"Orientácia je základom úniku aj vyzdvihnutia: bez presného určenia polohy nie je možné hlásenie ani nadviazanie kontaktu. Prostriedky: mapa, buzola, terénne predmety a posledná rezerva – slnko a hviezdy."}]},{"id":"6.2","title":"Odčítanie súradníc","web":true,"blocks":[{"t":"p","x":"Vojenské mapy používajú sieť MGRS/UTM: čiary siete sú na mape 1:50 000 vzdialené 1 km."},{"t":"ol","items":["Nájdi ľavý dolný roh štvorca, v ktorom je bod.","**„Doprava, potom hore“**: najprv odčítaj východnú (zvislú) hodnotu, potom severnú (vodorovnú).","Spresnenie desatinami (uhlomerom): 6 číslic = 100 m, 8 číslic = 10 m presnosť."]},{"t":"ok","x":"Príklad: 045-245 → východ 04,5 / sever 24,5 jednotky siete."}]},{"id":"6.3","title":"Meranie vzdialenosti na mape","web":true,"blocks":[{"t":"li","items":["Mierka 1:50 000 → 1 cm na mape = **500 m** v teréne; 1:25 000 → 1 cm = 250 m.","Priama vzdialenosť: pravítkom / mierkou 1:50 000 na buzole.","Kľukatá cesta: pásik papiera, niť alebo súčet úsekov.","V teréne: **počítanie dvojkrokov** – vopred si zmeraj, koľko dvojkrokov má 100 m (priemer 60–70); do kopca, v noci, so záťažou viac."]}]},{"id":"6.4","title":"Orientácia mapy","web":true,"blocks":[{"t":"p","x":"Na orientovanej mape súhlasia smery so smermi v teréne."},{"t":"ol","items":["**Buzolou:** hranu buzoly prilož k severnej čiare siete a otáčaj mapu s buzolou, kým magnetický sever nie je na značke (s ohľadom na deklináciu).","**Podľa terénnych predmetov:** otoč mapu podľa rovnej cesty, železnice alebo vzdialeného jasného bodu."]}]},{"id":"6.5","title":"Uhlomer (súradnicový merač)","web":true,"blocks":[{"t":"p","x":"Priehľadný hárok so stupnicou stupňov/dielcov a súradnicovými mierkami."},{"t":"li","items":["Meranie smeru na mape: stred na východiskový bod, 0° na sever siete, odčítaj smer k cieľu.","**Smerník siete** preveď na **magnetický azimut** podľa deklinačného diagramu mapy, než ho použiješ s buzolou."]}]},{"id":"6.6","title":"Meranie azimutu buzolou Cammenga 3H","web":true,"blocks":[{"t":"p","x":"Časti šošovkovej buzoly Cammenga: veko so zameriavacím drôtikom, okulár so šošovkou, plávajúci ciferník, otočný krúžok (cvakací), slučka na palec, mierka 1:50 000. Model 3H má tríciové podsvietenie viditeľné v noci bez nabíjania."},{"t":"p","x":"**Odčítanie azimutu (držanie pri líci):**"},{"t":"ol","items":["Otvor veko na 90°, okulár asi na 45° – ciferník sa musí voľne otáčať.","Palec prevlečený slučkou, ukazovák pozdĺž buzoly; druhou rukou ju podopri zospodu.","Zdvihni ju k oku, palec pri lícnej kosti.","Pozri cez okulár: cieľ zarovnaj so zameriavacím drôtikom.","Odčítaj azimut na ciferníku pod drôtikom."]},{"t":"p","x":"**Nastavenie smeru:** cvakací krúžok: 1 cvaknutie = **3°** (alebo 50 dielcov); 360° = 120 cvaknutí. V tme sa dá nastaviť počítaním cvaknutí."},{"t":"warn","x":"Pri kovových predmetoch, vozidlách, elektrickom vedení či zbrani buzola klame – odstúp (od zbrane aspoň 1–2 m, od vozidla 10+ m)."}]},{"id":"6.7","title":"Meranie azimutu v teréne","web":true,"blocks":[{"t":"p","x":"**Meranie:**"},{"t":"ol","items":["Vyber cieľ.","Zameraj ho drôtikom pri držaní pri líci.","Počkaj, kým sa ciferník ustáli, odčítaj.","Pre presnosť zopakuj."]},{"t":"p","x":"**Pochod podľa azimutu:**"},{"t":"ol","items":["Otoč ciferník (alebo nacvakaj krúžok) na požadovaný azimut.","Pri držaní pred telom sa otáčaj, kým ručička nie je pri svietiacej značke.","Vyber v tom smere terénny bod, choď k nemu a opakuj."]},{"t":"ok","x":"V noci: smer ukazuje zhoda dvoch svietiacich bodov a ručičky."}]},{"id":"6.8","title":"Bočné pretínanie","web":true,"blocks":[{"t":"p","x":"Ak si na známej línii (cesta, rieka, hrebeň):"},{"t":"ol","items":["Zmeraj azimut na známy terénny predmet identifikovaný na mape.","Vypočítaj spätný azimut (±180°).","Od predmetu nakresli na mape spätný azimut – kde pretne známu líniu, tam si."]}]},{"id":"6.9","title":"Spätné pretínanie","web":true,"blocks":[{"t":"p","x":"Ak je poloha neznáma:"},{"t":"ol","items":["Orientuj mapu, identifikuj **dva (radšej tri)** dobre viditeľné body, ktoré sú aj na mape, ideálne pod uhlom 60–120°.","Zmeraj ich azimuty, vypočítaj spätné azimuty (±180°).","Nakresli čiary z bodov – priesečník (stred trojuholníka) je tvoja poloha."]}]},{"id":"6.10","title":"Orientácia bez pomôcok","web":true,"blocks":[{"t":"li","items":["**Tieňová palica:** označ koniec tieňa zapichnutej palice, o 15 minút znova – prvý bod je západ, druhý východ.","**Hodinky:** na severnej pologuli nasmeruj hodinovú ručičku na slnko; os uhla medzi ňou a 12 (v letnom čase 1) ukazuje na juh.","**Polárka:** vzdialenosť dvoch zadných hviezd Veľkého voza predĺž päťkrát – sever."]},{"t":"warn","x":"Mach, letokruhy a mraveniská sú nespoľahlivé ukazovatele smeru."}]}]},{"id":"7","title":"Vyzdvihnutie – postupy link-up","sub":"III. časť, 1. lekcia — podľa osnovy učiva, doplnené z verejných zdrojov","sections":[{"id":"7.1","title":"Význam JPR","web":true,"blocks":[{"t":"p","x":"Záchrana osôb (Personnel Recovery, PR) je súhrn vojenského, diplomatického a civilného úsilia o záchranu a reintegráciu izolovaných osôb. Úspešná záchrana posilňuje morálku, bráni nepriateľovi zneužiť zajatú osobu na propagandu či získavanie informácií a zachováva vycvičený personál."}]},{"id":"7.2","title":"Základné pojmy","web":true,"blocks":[{"t":"li","items":["**ISOP (IP):** izolovaná osoba.","**JPR:** spoločná záchrana osôb.","**CSAR:** bojové pátranie a záchrana – jedna z metód úlohy „Recover“, nie synonymum PR.","**JPRC:** spoločné centrum záchrany osôb; **PRCC:** koordinačná bunka záchrany osôb.","**ISOPREP:** vopred vyplnený identifikačný hárok (otázky a odpovede, fotografia, odtlačky) na overenie totožnosti.","**EPA:** plán úniku (Evasion Plan of Action) – plánovaná trasa a zámer."]}]},{"id":"7.3","title":"Európske a národné súvislosti","web":true,"blocks":[{"t":"li","items":["**EDA (Európska obranná agentúra):** od roku 2013 spustila kurzy plánovačov a riadiacich záchrany osôb (PRCPC, neskôr JPRSC) pre interoperabilitu členských štátov.","**EPRC (Európske centrum pre záchranu osôb):** vzniklo 8. júla 2015, sídli na leteckej základni Poggio Renatico v Taliansku. Medzivládna vojenská organizácia na zosúladenie pravidiel a výcviku PR."]},{"t":"ok","x":"Maďarsko je aktívne: veliteľsko-riadiace centrum letectva vo Veszpréme pravidelne hostí štábne kurzy EDA JPR s maďarskými inštruktormi."}]},{"id":"7.4","title":"Operačné prvky: JPRC, PRCC","web":true,"blocks":[{"t":"li","items":["**JPRC:** na úrovni operačného veliteľstva riadi a koordinuje celú činnosť PR na bojisku.","**PRCC:** koordinuje záchranu na úrovni zložiek/štátov, je v spojení s JPRC.","**Prepojenie:** v operáciách NATO, EÚ a OSN sa národné prvky PR pripájajú k mnohonárodnej štruktúre; cieľom je jednotný postup a rýchla pomoc."]}]},{"id":"7.5","title":"Fázy systému JPR","web":true,"blocks":[{"t":"ol","items":["**Príprava:** výcvik (SERE), výstroj, ISOPREP, plánovanie.","**Plánovanie:** plány PR, EPA, komunikačné postupy.","**Vykonanie:** päť základných úloh.","**Vyhodnotenie:** spracovanie skúseností."]}]},{"id":"7.6","title":"Vzdelávanie a výcvik","web":true,"blocks":[{"t":"p","x":"Záchrana osôb stojí na troch pilieroch: velitelia a štáby, záchranné sily a samotná **izolovaná osoba**. Pripravenosť izolovanej osoby (SERE, ISOPREP, EPA, výstroj) rozhodujúco ovplyvňuje úspech záchrany."}]},{"id":"7.7","title":"Päť základných úloh PR","web":true,"blocks":[{"t":"ol","items":["**Report – hlásenie:** začína rozpoznaním izolujúcej udalosti; musí byť rýchle a presné.","**Locate – lokalizácia:** nájdenie a overenie osoby; záchranné sily vyrážajú až po presnej polohe a istej identifikácii.","**Support – podpora:** podpora osoby a jej rodiny – obojsmerná komunikácia, zhadzovanie zásob, potlačenie nepriateľa.","**Recover – záchrana:** koordinovaná činnosť veliteľov, záchranných síl a izolovanej osoby.","**Reintegrate – reintegrácia:** lekárska prehliadka, rozbor, návrat do služby a k rodine – na prvom mieste je telesné a duševné zdravie."]},{"t":"ok","x":"Izolovaná osoba sa zapája tiež: ak sa ozve rádiom, pomáha úlohám Report a Locate."}]},{"id":"7.8","title":"Medzinárodné nasadenie","web":true,"blocks":[{"t":"p","x":"Vojaci v operáciách NATO a EÚ (napr. KFOR) slúžia v prostredí, kde je systém PR dostupný – pripravenosť SERE doň zapadá."}]},{"id":"7.9","title":"Cieľ link-upu","web":true,"blocks":[{"t":"p","x":"Cieľom nadviazania kontaktu (link-up) je, aby sa izolovaná osoba a záchranné/vlastné sily stretli **bezpečne a so vzájomným overením** – bez paľby do vlastných a bez nepriateľskej pasce."}]},{"id":"7.10","title":"Kroky pred fyzickým kontaktom","web":true,"blocks":[{"t":"ol","items":["Dosiahni určené miesto vyzdvihnutia/zhromaždenia a sleduj okolie.","Ohlás sa podľa určeného postupu (rádio, signál) – len na pokyn.","Priprav signalizačné prostriedky (zrkadlo, svetlica, stroboskop, IR signál, panel).","Výstroj: zbraň zaistená, v rukách nič podozrivé.","Presne sa riaď pokynmi záchranných síl."]},{"t":"warn","x":"Pre záchranné sily je neznáma ozbrojená osoba hrozbou – ruky maj viditeľné."}]},{"id":"7.11","title":"Overenie totožnosti","web":true,"blocks":[{"t":"li","items":["**Otázky ISOPREP:** vopred určené osobné otázky, na ktoré pozná odpoveď len izolovaná osoba.","**Číselné, písmenové, farebné kódy:** podľa denných/operačných kódov.","**Zvukové, ručné, svetelné signály:** vo vopred dohodnutom poradí.","**Kontrola:** záchranné sily môžu izolovanú osobu položiť na zem a prehľadať – je to bezpečnostný postup, nie nepriateľstvo."]}]},{"id":"7.12","title":"Skutočný príklad – Líbya 2011","web":true,"blocks":[{"t":"ol","items":["marca 2011 počas operácie Odyssey Dawn havarovalo pri Benghází pre technickú poruchu americké lietadlo F-15E Strike Eagle. Dvojčlenná posádka sa katapultovala, no dopadla ďaleko od seba."]},{"t":"li","items":["Pilota vyzdvihla jednotka námornej pechoty **TRAP** vyslaná z lode USS Kearsarge (2 MV-22 Osprey, 2 CH-53E, 2 AV-8B Harrier) približne do 90 minút od hlásenia; na zemi strávila menej ako 90 sekúnd.","Zbraňového dôstojníka našli miestni povstalci a neskôr ho odovzdali americkým silám."]},{"t":"ok","x":"Poučenie: rýchle hlásenie, presná poloha a overenie, záchranné sily v pohotovosti – a pripravená izolovaná osoba."}]}]},{"id":"8","title":"Čo sa očakáva od zachraňovanej osoby","sub":"III. časť, 2. lekcia — podľa osnovy učiva, doplnené z verejných zdrojov","sections":[{"id":"8.1","title":"Udržanie života","web":true,"blocks":[{"t":"p","x":"Poradie potrieb izolovanej osoby – priority SERE:"},{"t":"ol","items":["**Osobná ochrana:** prvá pomoc, prístrešok, odev, oheň – proti počasiu a nepriateľovi.","**Zásoby – voda a jedlo:** voda je pred jedlom.","**Zdravie – telesné a psychické:** ošetrenie zranení, hygiena, spánok, morálka, vôľa prežiť.","**Presun:** len s dobrým dôvodom a plánom – buď čakať na záchranu na mieste, alebo únik/návrat."]},{"t":"ok","x":"Pomôcka: **„pravidlo troch“** – 3 minúty bez vzduchu, 3 hodiny bez ochrany v extrémnom počasí, 3 dni bez vody, 3 týždne bez jedla."}]},{"id":"8.2","title":"Zachovanie dôstojnosti","web":true,"blocks":[{"t":"li","items":["**Zajatie – horšie ako únik!** Využi každú možnosť, aby si sa vyhol zajatiu.","**Odpor:** v zajatí sa izolovaná osoba riadi pravidlami správania: uvedie len údaje povinné podľa medzinárodného práva (Ženevské dohovory) – meno, hodnosť, dátum narodenia, služobné číslo; nespolupracuje s nepriateľom, nerobí propagandistické vyhlásenia.","**Útek:** ak sa naskytne príležitosť a riziko je prijateľné, je povinnosťou usilovať sa o útek – najvýhodnejšie sú prvé hodiny po zajatí."]},{"t":"ok","x":"Viera, kamarátstvo, rutina a disciplína: základy psychického prežitia zajatia."}]},{"id":"8.3","title":"Príprava pred nasadením","web":true,"blocks":[{"t":"li","items":["Vyplň a aktualizuj ISOPREP; poznaj EPA (plán úniku).","Komunikačný plán: frekvencie, volacie znaky, kódy, časové okná ohlásenia.","Skontroluj súpravu na prežitie a signalizačné prostriedky na tele.","Poznaj priestor: mapa, miesta vyzdvihnutia, zhromaždiská, nebezpečné oblasti."]}]},{"id":"8.4","title":"Nahlásenie izolujúcej udalosti","web":true,"blocks":[{"t":"li","items":["Hlás, len čo sa dá: kto, kde, kedy, stav, zámer, hrozba.","S rádiom: krátke kódované vysielanie v určenom okne zo skrytého miesta – potom zmeň miesto.","Bez rádia: signalizačné prostriedky v správnom čase na mieste vyzdvihnutia."]}]},{"id":"8.5","title":"Informovanie záchranných síl","web":true,"blocks":[{"t":"li","items":["Presná poloha (súradnice), spôsob overenia, zranenia, nepriateľské sily, terén a pristávacia plocha.","Počúvaj a riaď sa pokynmi; zbytočne nevysielaj."]}]},{"id":"8.6","title":"Miesto záchrany","web":true,"blocks":[{"t":"li","items":["Skrytá blízkosť určeného miesta a dosť otvoreného priestoru pre záchranný prostriedok.","Pristávacia plocha bez prekážok (vrtuľník: bez stromov, vedení, voľných predmetov); smer vetra.","Signalizuj len pri priblížení záchranných síl / na pokyn."]}]},{"id":"8.7","title":"Fyzický kontakt v skratke","web":true,"blocks":[{"t":"ol","items":["Signalizuj podľa pokynov.","Zbraň zaistená, ruky viditeľné, nebež k záchrannému prostriedku.","Over svoju totožnosť (otázky ISOPREP).","Strpi prehliadku, riaď sa pokynmi záchranných síl.","Pri nastupovaní podľa pokynov záchranných síl – hlavu dolu, ďalej od rotora."]}]}]},{"id":"B1","title":"Pokročilé zakladanie ohňa, prístrešok, počasie","sub":"BRAVO · podľa ATP 3-50.21 a AFH 10-644","sections":[{"id":"B1.1","title":"Oheň bez zápaliek a zapaľovača","web":true,"blocks":[{"t":"p","x":"Na úrovni B jeden zapaľovač nestačí: maj aspoň dva ďalšie spôsoby, ako založiť oheň, a precvič ich za sucha aj za mokra."},{"t":"li","items":["**Ferocéričková tyčinka (kresadlo):** chrbtom noža alebo škrabkou ťahaj nadol tesne nad podpaľovačom; funguje aj v daždi.","**Lupa, okuliare, priehľadná fľaša s vodou:** sústreď slnečné svetlo do jedného bodu a tmavý podpaľovač sa vznieti.","**Batéria + oceľová vlna:** dva póly 9 V batérie alebo dve tužkové batérie zapojené za sebou okamžite rozžhavia jemnú oceľovú vlnu.","**Lukový vrták:** suché mäkké drevo (lipa, topoľ, vŕba), zárez v podložke, rovnomerný, zrýchľujúci sa ťah – vyžaduje veľa cviku."]},{"t":"p","x":"**Podpaľovač za mokra:** vnútro stojaceho suchého dreva, „pierkové“ triesky (tenké hobliny nechané na paličke), brezová kôra (olejnatá, horí aj mokrá), živičný pník borovice."},{"t":"warn","x":"Jeden zapaľovač nie je žiadny zapaľovač. V súprave na prežitie maj viac spôsobov, vodotesne zabalených, na tele."}]},{"id":"B1.2","title":"Typy ohňa podľa úlohy","web":true,"blocks":[{"t":"li","items":["**Pyramída:** rýchlo sa rozhorí; na varenie a signalizáciu.","**Zrub (krížom kladené polená):** dáva veľa žeravých uhlíkov a drží teplo; na varenie.","**Hviezda (polená lúčovito, horí v strede):** horí pomaly a úsporne; v noci posúvaš polená dovnútra.","**Indiánske ohnisko (Dakota):** dve prepojené jamy (ohnisko + vzduchový kanál); nízky plameň, málo dymu a svetla – skrytý oheň.","**Odrazová stena:** z polien alebo kameňov za ohňom; smeruje teplo k prístrešku."]},{"t":"ok","x":"Na nepriateľskom území: malý oheň zo suchého tvrdého dreva, pod korunami; cez deň prezrádza dym, v noci svetlo. Ak nemusíš, oheň nezakladaj."}]},{"id":"B1.3","title":"Pokročilé prístrešky","web":true,"blocks":[{"t":"li","items":["**Prístrešok so šikmou strechou + odrazová stena:** zadnou stranou k vetru, vpredu oheň, za ním stena – najteplejšie jednoduché riešenie.","**Chatrč z lístia:** hrebeňová žrď a rebrá, na ne 60–90 cm hrubá vrstva suchého lístia; teplá aj bez ohňa, len o málo väčšia ako tvoje telo.","**Celta do tvaru A:** šnúra medzi dvoma stromami, celta na nej napnutá; rýchle, najlepšie do dažďa.","**Snežný zákop a snežná jaskyňa:** sneh dobre izoluje. Vchod nižšie ako lôžko (studený vzduch odteká), vždy vetrací otvor, lopatku maj vnútri.","**Hojdacia sieť, zvýšené lôžko:** nad mokrou zemou alebo zemou plnou živočíchov."]},{"t":"warn","x":"Oheň alebo varič v snežnej jaskyni či stane: otrava oxidom uhoľnatým. Vždy vetraj!"}]},{"id":"B1.4","title":"Poranenia chladom a teplom","web":true,"blocks":[{"t":"p","x":"**Podchladenie (hypotermia)** – príznaky: silná triaška, potom nemotornosť, potkýnanie, mrmlanie, zmätenosť, nakoniec triaška prestane – to je už ohrozenie života."},{"t":"li","items":["Postup: suché miesto chránené pred vetrom, izolácia zospodu aj zhora, suchý odev, teplý (nie horúci) sladký nápoj, ak je pri vedomí, telesné teplo."]},{"t":"p","x":"**Omrzlina:** biela, voskovitá, necitlivá koža."},{"t":"li","items":["Netri ju, nezohrievaj pri ohni. Rozmrazuj telesným teplom len vtedy, ak už nemôže znova zamrznúť."]},{"t":"p","x":"**Vyčerpanie z tepla:** bledá, vlhká koža, slabosť, bolesť hlavy → tieň, odpočinok, voda + soľ."},{"t":"p","x":"**Úpal / prehriatie:** horúca, červená koža, zmätenosť, bezvedomie → **okamžité chladenie** (voda, mokrá látka, vietor), ohrozenie života."},{"t":"p","x":"**Zákopová noha:** nohy dlhé dni mokré a studené. Prevencia: suché ponožky na noc, každodenná starostlivosť o nohy."}]}]},{"id":"B2","title":"Voda a jedlo v teréne","sub":"BRAVO · podľa ATP 3-50.21 a AFH 10-644","sections":[{"id":"B2.1","title":"Pokročilé získavanie vody","web":true,"blocks":[{"t":"li","items":["**Transpiračné vrecko:** priehľadné vrecko priviazané na živý, slnečný, olistený konár; rastlina môže za deň dať pohár či dva vody. Nikdy nie na jedovatú rastlinu.","**Solárny destilátor:** jama široká asi 1 m, v strede nádoba, nad ňou fólia s malým kameňom v strede. Málo vody za veľa práce – najlepšie na úpravu slanej alebo znečistenej vody.","**Rosa:** za úsvitu ju zotri z trávy handrou a vyžmýkaj.","**Rastliny:** brezová a javorová miazga na jar, odrezaný výhonok divého viniča kvapká.","**Sneh a ľad:** roztop ich, nejedz (podchladzujú a odvodňujú). Na dno nádoby daj trochu vody, aby sa nepripálila."]},{"t":"warn","x":"Každú prírodnú vodu uprav: varenie, tablety alebo filter + dezinfekcia. Samotná filtrácia choroboplodné zárodky nezničí."}]},{"id":"B2.2","title":"Jedlé a jedovaté rastliny","web":true,"blocks":[{"t":"p","x":"Jedz len to, čo **s istotou poznáš**. Rastlinná potrava dáva málo energie, ale vitamíny a vlákninu áno."},{"t":"li","items":["**Bezpečné a ľahko rozpoznateľné (stredná Európa):** pŕhľava (varená), púpava, skorocel, šťavel, divé maliny, ostružiny, šípky, lieskovce, žalude (vylúhované vo viacerých vodách), vnútorná kôra borovice, čaj z ihličia.","**Vyhýbaj sa:** rastlinám s mliečnou šťavou, s vôňou horkých mandlí, s okolíkovým kvetenstvom (bolehlav!), s trojitými listami, bielym a žltým bobuliam.","**Huby v teréne nikdy nejedz** – smrteľne jedovaté druhy sa dajú zameniť s jedlými.","**Tis:** každá jeho časť je smrteľne jedovatá (aj semeno v červenej bobuli) – nevar z neho čaj."]},{"t":"p","x":"**Skúška jedlosti (len v krajnej núdzi, ak dni nemáš nič iné):** jedna časť rastliny, najprv na kožu, potom na peru, jazyk, potom malé sústo a čakanie 8 hodín. Zdĺhavé a nechráni pred každým jedom."}]},{"id":"B2.3","title":"Živočíšna potrava","web":true,"blocks":[{"t":"li","items":["**Hmyz:** najľahšie dostupná bielkovina (larvy, kobylky, mravčie kukly). Vždy uvar alebo opeč. Vyhýbaj sa chlpatému, pestrofarebnému, bodavému a zapáchajúcemu.","**Ryby:** improvizovaný háčik (ihla, tŕň), vlasec, návnada; vrša v plytkej vode; rybu vždy dôkladne opeč.","**Drobná zver do slučiek:** na zverných chodníkoch, v zúženiach, pred norou. Veľa slučiek, kontrola aspoň raz denne."]},{"t":"warn","x":"V mieri sú poľovníctvo, chytanie do pascí a rybolov viazané na povolenie. Tieto spôsoby sú len na skutočnú situáciu prežitia."},{"t":"ok","x":"Človek vydrží bez jedla týždne, bez vody len dni. Získavanie jedla nesmie spotrebovať viac energie, než prinesie."}]},{"id":"B2.4","title":"Príprava a uskladnenie jedla","web":true,"blocks":[{"t":"li","items":["Zviera spracuj ďalej od vodného zdroja a tábora; zvyšky zakopaj (pach, predátori, stopy).","Všetko dôkladne uvar alebo upeč: najlepšia ochrana pred parazitmi a baktériami.","**Konzervovanie:** nakrájané na tenké pásiky údiť alebo sušiť na slnku a vetre.","Varenie zachová najviac živín – vypi aj vývar.","Na nepriateľskom území ťa pach a dym varenia prezradí: ak sa dá, jedz tam studené jedlo."]}]}]},{"id":"B3","title":"Pokročilá navigácia","sub":"BRAVO · podľa ATP 3-50.21 a FM 3-25.26","sections":[{"id":"B3.1","title":"Orientácia podľa hviezd","web":true,"blocks":[{"t":"li","items":["**Polárka (severná pologuľa):** nájdi Veľký voz a vzdialenosť medzi dvoma zadnými hviezdami „voza“ odmeraj päťkrát nahor – tam je Polárka, pod ňou na obzore je sever.","**Kasiopeja:** súhvezdie v tvare „W“ oproti Veľkému vozu, na druhej strane Polárky – pomôže, keď je Veľký voz zakrytý.","**Orionov pás:** vychádza na východe, zapadá na západe; rad troch hviezd smeruje približne východ–západ."]},{"t":"p","x":"**Metóda pohybu hviezd:** dve palice v jednej línii namier na hviezdu a po 15–20 minútach pozri, kam sa pohla. Nahor → pozeráš na východ, nadol → na západ, doprava → na juh, doľava → na sever."}]},{"id":"B3.2","title":"Slnko a hodinky","web":true,"blocks":[{"t":"li","items":["**Tieňová palica:** palicu zapichni do zeme, označ koniec tieňa; po 15 minútach ho označ znova. Prvý bod je západ, druhý východ, spojnica je smer východ–západ.","**Ručičkové hodinky (severná pologuľa):** malú ručičku natoč na Slnko; os uhla medzi malou ručičkou a 12 ukazuje na juh. V letnom čase použi namiesto 12 číslo 1.","**Na poludnie** (miestneho času) je Slnko na juhu, tieň je najkratší a ukazuje na sever."]},{"t":"warn","x":"Mach, letokruhy a mravenisko nie sú spoľahlivým ukazovateľom smeru – nestavaj na nich."}]},{"id":"B3.3","title":"Mŕtvy výpočet a vzdialenosť","web":true,"blocks":[{"t":"p","x":"**Mŕtvy výpočet:** zo známeho bodu postupuješ v známom smere (azimut) odmeranú vzdialenosť a priebežne počítaš, kde si."},{"t":"li","items":["**Dvojkroky:** vopred si odmeraj svoju hodnotu na 100 m (rovina, svah, hustý porast zvlášť). Označ každých 100 m (uzol na šnúre, kamienok vo vrecku).","**Obchádzanie prekážky:** odboč v pravom uhle a počítaj kroky, pokračuj v pôvodnom smere a nakoniec sa vráť na líniu rovnakým počtom krokov.","**Zámerná odchýlka:** ak hľadáš bod na líniovom objekte (cesta, potok), mier zámerne na jednu jeho stranu – budeš vedieť, kam odbočiť, keď ho dosiahneš.","V noci a v hmle sa vzdialenosti zdajú dlhšie a krok je kratší – počítaj s tým."]}]},{"id":"B3.4","title":"Čítanie terénu","web":true,"blocks":[{"t":"li","items":["**Zábradlie:** líniový objekt (potok, hrebeň, okraj lesa, elektrické vedenie), pozdĺž ktorého isto postupuješ bez neustálej orientácie.","**Záchytný bod:** objekt za tvojím cieľom; keď ho dosiahneš, vieš, že si ho prešiel a máš sa vrátiť.","**Hrebeň, sedlo, údolie, výbežok:** tvary vrstevníc – cvič porovnávanie mapy so skutočným terénom.","Keď si neistý: zastav (S-T-O-P), vráť sa k poslednému istému bodu, nehádaj."]},{"t":"ok","x":"V teréne voda tečúca nadol (potok → rieka) obvykle vedie k osadám a cestám – pri úniku sú však práve tieto miesta nebezpečné."}]}]},{"id":"B4","title":"Únik v teréne, signalizácia, nadviazanie kontaktu","sub":"BRAVO · podľa FM 21-76-1 a ATP 3-50.21","sections":[{"id":"B4.1","title":"Plánovanie pohybu na nepriateľskom území","web":true,"blocks":[{"t":"li","items":["**Cyklus:** pozoruj → pohybuj sa → pozoruj. Krátke úseky, časté zastavenia, vždy vedz, kam sa skryješ, ak treba.","**Denná doba:** pohybuj sa pred úsvitom, za súmraku a v noci; cez deň odpočívaj v úkryte.","**Trasa:** hustý porast, terénne zníženiny, tienisté svahy. Vyhýbaj sa cestám, chodníkom, hrebeňom, otvorenému priestoru a osadám.","**Prechod cez cestu:** v zákrute alebo tam, kde je výhľad najkratší; najprv dlho pozoruj, potom kolmo, rýchlo, po jednom.","**Prechod cez potok:** na najširšom a najplytšom mieste, v obuvi, šikmo proti prúdu; náhradný odev drž v suchu."]},{"t":"warn","x":"Netrpezlivosť a únava sú hlavnými príčinami odhalenia. Radšej pomaly, ale nepozorovane."}]},{"id":"B4.2","title":"Stopy a ich zahladzovanie","web":true,"blocks":[{"t":"p","x":"Všetko, čo zanecháš, sa dá nájsť: odtlačky nôh, zlomené vetvičky, pošliapaná tráva, zotretá rosa, prevrátené kamene, odpadky, pach, výkaly."},{"t":"li","items":["Stúpaj na tvrdú zem, kamene, korene a lístie; mäkkej, blatistej pôde sa vyhýbaj.","Konáre nelám, ohni ich a nechaj vrátiť.","Odpadky a výkaly zakopaj, úkryt zanechaj tak, ako si ho našiel.","Brodiť sa vodou sa oplatí len na krátkom úseku – podchladí ťa a miesto výstupu ťa prezradí.","Nevracaj sa tou istou cestou; striedaj smer, ale drž hlavný smer."]}]},{"id":"B4.3","title":"Ochrana pred pozorovaním","web":true,"blocks":[{"t":"li","items":["**Dron, letecký prieskum:** keď ho počuješ, **znehybni** – pohyb je najnápadnejší. Zostaň pod korunami, v tieni, medzi nepravidelnými tvarmi.","**Termovízia:** telesné teplo svieti pred studeným pozadím. Kry sa za zeminu, skaly, hustý porast; otvorený terén nemá dobrý úkryt.","**Nočné videnie:** aj najmenšie svetlo je vidieť zďaleka: telefón, hodinky, cigareta.","**Pátranie so psom:** pes sleduje pach, nie zrak. Čas a vzdialenosť sú najlepšou ochranou – pokračuj v pohybe, nepanikár, nesnaž sa bojovať.","**Elektronika:** zapnutý telefón prezrádza polohu. Zapni ho len v plánovanom časovom okne."]}]},{"id":"B4.4","title":"Improvizovaná signalizácia a nadviazanie kontaktu","web":true,"blocks":[{"t":"li","items":["**Signálne zrkadlo:** dvoma prstami vytvor V, cieľ (lietadlo) zachyť do V a svetelnú škvrnu priveď medzi prsty. Za slnka je viditeľné na desiatky kilometrov.","**Pozemné signály** (aspoň 3 m dlhé, kontrastné): **V** potrebujem pomoc, **X** potrebujem lekársku pomoc, **N** nie, **Y** áno, **→** idem týmto smerom.","**Rádio / telefón:** len v časovom okne podľa komunikačného plánu, krátkou správou (kto, kde, stav).","**Kontakt so záchrancami:** zostaň skrytý, kým ich neidentifikuješ; zbraň zaistená, ruky na očiach, neutekaj k nim; presne plň pokyny, odpovedaj na overovacie otázky (ISOPREP)."]},{"t":"ok","x":"Signalizácia je dvojsečná: vidia ju záchrancovia aj nepriateľ. Najprv zváž hrozbu."}]}]},{"id":"C1","title":"Riziko zajatia a jeho predchádzanie","sub":"CHARLIE · podľa AFH 10-644 a verejných zdrojov NATO","sections":[{"id":"C1.1","title":"Pre koho je úroveň C?","web":true,"blocks":[{"t":"p","x":"Úroveň C je pre osoby s **vysokým rizikom**: tých, u ktorých je pre ich úlohu, funkciu alebo hodnosť veľká pravdepodobnosť izolovania a zajatia a ktorí nesú pre nepriateľa mimoriadne cenné informácie."},{"t":"li","items":["Letecký personál, sily špeciálnych operácií, prieskumníci, hĺbkové hliadky.","Styčné a pozorovacie tímy, osoby slúžiace v zahraničí, vysokí funkcionári.","Aj v mieri: riziko únosu alebo svojvoľného zadržania v zahraničí."]},{"t":"warn","x":"Podstatou úrovne C je praktický výcvik v kontrolovaných podmienkach so skúsenými inštruktormi. Táto kapitola dáva len teoretický základ, kurz nenahrádza."}]},{"id":"C1.2","title":"Príprava pred odchodom","web":true,"blocks":[{"t":"li","items":["**ISOPREP:** vyplň ho a udržuj aktuálny; záchrancovia ťa podľa týchto osobných otázok overia.","**Plán úniku (EPA):** trasa, zhromaždiská, signály, časové okná – v hlave, nie na papieri.","**Osobné veci:** len to, čo úloha vyžaduje. Neber listy, fotografie, poznámky ani zbytočné doklady; v telefóne nemaj nič, čo by vydalo napospas teba, rodinu alebo jednotku.","**Súprava na prežitie na tele:** ak stratíš batoh alebo vozidlo, táto ti zostane.","**Kondícia a zdravie:** zajatie aj únik skúšajú aj telo."]}]},{"id":"C1.3","title":"Okamih zajatia","web":true,"blocks":[{"t":"p","x":"Zajatie je jednou z najnebezpečnejších fáz: väznitelia sú napätí, situácia je chaotická."},{"t":"li","items":["Ak je odpor beznádejný, **neprovokuj**: ruky na očiach, pomalé pohyby, plň pokyny.","Zostaň pokojný a pozoruj: koľkí sú, kam ťa vedú, čo vidíš a počuješ – neskôr to môže byť potrebné na útek.","Žiadaj ošetrenie pre seba aj zranených kamarátov.","Nezačínaj rozhovory, nešpekuluj nahlas, nevyhrážaj sa."]},{"t":"ok","x":"Správanie v prvých hodinách veľa znamená: na pokojného, disciplinovaného zajatca sa menej zameriava násilie."}]},{"id":"C1.4","title":"Útek v počiatočnej fáze","web":true,"blocks":[{"t":"p","x":"Podľa verejných doktrín býva najlepšia šanca na útek často **krátko po zajatí**: vlastné sily sú ešte blízko, väznitelia neorganizovaní a ty si ešte v plnej sile."},{"t":"li","items":["Zváž: aká je šanca, aké je tvoje zdravie, kam by si šiel, čo by znamenal neúspech – pre teba aj tvojich kamarátov.","Ak ideš: hneď, rozhodne, a potom uplatni pravidlá úniku (B4).","Ak nie: pozoruj, zbieraj informácie, šetri sily na neskoršiu príležitosť."]}]}]},{"id":"C2","title":"Práva a správanie vojnového zajatca","sub":"CHARLIE · podľa III. Ženevského dohovoru a AFH 10-644","sections":[{"id":"C2.1","title":"Ochrana III. Ženevského dohovoru","web":true,"blocks":[{"t":"p","x":"Vojak zajatý v medzinárodnom ozbrojenom konflikte je **vojnový zajatec** a chráni ho III. Ženevský dohovor (1949)."},{"t":"li","items":["Patrí mu ľudské zaobchádzanie; mučenie, zastrašovanie a verejné ponižovanie sú zakázané.","Má nárok na jedlo, vodu, odev, ubytovanie a lekársku starostlivosť.","Môže si dopisovať s rodinou a môže ho navštíviť Medzinárodný výbor Červeného kríža (MVČK).","**Pri výsluchu je povinný uviesť len štyri údaje:** priezvisko a mená, hodnosť, dátum narodenia, osobné (služobné) číslo. Iné informácie z neho nemožno vynútiť (článok 17)."]},{"t":"warn","x":"Nie každý protivník dohovor dodržiava. Znalosť práv ti aj tak dáva silu a je základom neskoršieho vyvodenia zodpovednosti."}]},{"id":"C2.2","title":"Aj v zajatí zostávaš vojakom","web":true,"blocks":[{"t":"li","items":["Zajatie neruší vojenskú disciplínu: najstarší zajatec velí, ostatní ho podporujú.","Pomáhaj kamarátom; neprijímaj výhody, ktoré im škodia.","Nerob vyhlásenia a nepodpisuj nič, čo by sa dalo použiť proti tvojej krajine, spojencom alebo kamarátom.","Zachovaj si ľudskú dôstojnosť: hygiena, poriadok, držanie tela – to všetko je súčasť prežitia."]}]},{"id":"C2.3","title":"Výsluch – všeobecné zásady","web":true,"blocks":[{"t":"p","x":"Cieľom výsluchu je získať informácie a často aj propagandu."},{"t":"li","items":["Drž sa štyroch údajov a zvyšok zdvorilo a pokojne odmietaj.","Metódy sú rôzne: láskavosť, sľuby, únava, izolácia, zavádzajúce „informácie“ o kamarátoch. Počítaj s nimi a nenechaj sa zaskočiť.","Never tomu, že „ostatní už všetko povedali“.","Ak urobíš chybu, nevzdávaj sa: pri ďalšej otázke sa vráť k východiskovému postoju."]},{"t":"ok","x":"Konkrétne techniky odporu s tebou nacvičia inštruktori kurzu úrovne C v kontrolovaných podmienkach."}]},{"id":"C2.4","title":"Zadržanie v mieri a rukojemnícka situácia","web":true,"blocks":[{"t":"p","x":"Počas mierových operácií, misií či ciest do zahraničia zadržaná osoba **nie je vojnový zajatec**, preto je situácia iná."},{"t":"li","items":["Prvé minúty sú najnebezpečnejšie: nekladaj odpor ozbrojencom, plň pokyny.","Zostaň v očiach väzniteľov človekom: meno, rodina, pokojný hlas – nebuď podlízavý, ale ani neprovokuj.","Jedz, pi a spi, keď sa dá; drž svoj režim.","Pri záchrannej akcii: **ľahni si**, ruky na očiach, neutekaj, nesiahaj po ničom, plň pokyny záchrancov – spočiatku považujú za podozrivého každého."]}]}]},{"id":"C3","title":"Psychická odolnosť a prežitie v zajatí","sub":"CHARLIE · podľa AFH 10-644","sections":[{"id":"C3.1","title":"Stres a vôľa prežiť","web":true,"blocks":[{"t":"p","x":"Najväčším nepriateľom v zajatí často nie je väzniteľ, ale beznádej."},{"t":"li","items":["Strach, hnev, pocit viny a poruchy spánku sú normálne – normálne reakcie na mimoriadnu situáciu.","**Viera a cieľ:** rodina, kamaráti, návrat domov, viera alebo tvoje hodnoty – drž sa toho, čo ti dáva silu.","Mysli na to, že tvoja krajina a spojenci pracujú na tvojom oslobodení."]},{"t":"ok","x":"Podľa navrátených vojnových zajatcov bola kľúčom k prežitiu nádej a malé denné ciele."}]},{"id":"C3.2","title":"Denný režim","web":true,"blocks":[{"t":"li","items":["**Cvičenie:** aj v malom priestore: drepy, kľuky, strečing – údržba tela aj duše.","**Duševné cvičenie:** uč sa, plánuj, vybavuj si spomienky, postav v duchu dom, rieš úlohy.","**Hygiena:** umývaj sa, ako sa dá, udržuj poriadok na svojom mieste.","**Jedlo a pitie:** zjedz, čo dostaneš, aj keď je zlé – potrebuješ silu.","**Zmysel pre čas:** počítaj dni, vytvor si denný režim."]}]},{"id":"C3.3","title":"Kontakt s ostatnými zajatcami","web":true,"blocks":[{"t":"li","items":["Kamaráti sa navzájom udržiavajú pri živote: dávajte na seba pozor, deľte sa o silu.","Najstarší zajatec vedie skupinu a velenie funguje aj v zajatí.","Väznitelia sa snažia komunikácii zabrániť. Vojnoví zajatci vo Vietname napríklad používali verejne známy **klopací kód**: tabuľka písmen 5×5, najprv sa vyklope číslo riadku, potom stĺpca.","Nešír klebety, neobviňuj kamarátov – rozdelenie pomáha väzniteľovi."]}]},{"id":"C3.4","title":"Zdravie v zajatí","web":true,"blocks":[{"t":"li","items":["Ohlás chorobu alebo zranenie a žiadaj ošetrenie – je to tvoje právo.","Rany udržuj čo najčistejšie; sleduj príznaky infekcie (začervenanie, opuch, horúčka, zápach).","Voda a jedlo môžu byť vzácne: rozlož si sily, odpočívaj, keď sa dá.","Sleduj aj psychický stav kamarátov: kto sa uzavrie, neje, vzdáva sa – ten vás potrebuje."]}]}]},{"id":"C4","title":"Útek, vyzdvihnutie a reintegrácia","sub":"CHARLIE · podľa AFH 10-644 a verejných zdrojov NATO","sections":[{"id":"C4.1","title":"Rozhodnutie o úteku","web":true,"blocks":[{"t":"li","items":["**Kedy?** Čím skôr, tým väčšia šanca – ale len ak je situácia priaznivá. Neskorší útek dôkladne naplánuj.","**Zváž:** fyzický stav, znalosť terénu, kde sú vlastné sily, čo sa stane s kamarátmi, ak odídeš.","**Príprava:** zbieraj informácie (striedanie stráží, terén, počasie), šetri sily a ak sa dá, aj jedlo.","**Potom:** okamžite pravidlá úniku (B4) – pohyb v noci, zahladzovanie stôp, kontakt podľa plánu."]},{"t":"warn","x":"Neúspešný útek môže mať vážne následky. Rozhodnutie je tvoja zodpovednosť, ak sa dá, s vedomím najstaršieho zajatca."}]},{"id":"C4.2","title":"Vyzdvihnutie a oslobodenie","web":true,"blocks":[{"t":"li","items":["Záchranné sily konajú rýchlo a rozhodne a každého považujú za nebezpečného, kým ho neidentifikujú.","**Neutekaj k nim.** Ľahni si alebo zostaň na mieste, ruky na očiach, nesiahaj po ničom.","Plň pokyny doslova, strp prehliadku a spútanie.","Overenie: odpovedaj na otázky ISOPREP, povedz, kde sú ďalší kamaráti."]},{"t":"ok","x":"V okamihu záchrany disciplína zachraňuje životy – aj tvoj."}]},{"id":"C4.3","title":"Reintegrácia","web":true,"blocks":[{"t":"p","x":"Prepustenie nie je koniec príbehu. Proces reintegrácie v krajinách NATO má viac fáz:"},{"t":"ol","items":["**Lekárska starostlivosť a odpočinok:** posúdenie telesného stavu, liečba.","**Debriefing:** to, čo vieš, môže pomôcť tým, ktorí sú ešte v zajatí, aj budúcemu výcviku.","**Psychologická podpora:** odborník ti pomôže spracovať, čo sa stalo.","**Postupný návrat** k rodine a do služby."]},{"t":"li","items":["Poruchy spánku, podráždenosť, pocit viny či uzavretosť trvajúce mesiace sú normálne. Dajú sa liečiť – požiadaj o pomoc a prijmi ju."]}]},{"id":"C4.4","title":"Čo môžeš urobiť už teraz","web":true,"blocks":[{"t":"li","items":["Vyplň a aktualizuj ISOPREP; vedz naspamäť komunikačný plán a plán úniku.","Udržuj si kondíciu a vedomosti o prežití (úrovne A a B).","Daj do poriadku svoje doklady, povedz rodine, na koho sa obrátiť, ak sa niečo stane.","Cvič zvládanie stresu: dýchanie, režim, malé ciele.","Prihlás sa na oficiálny kurz úrovne B alebo C, ak to tvoja funkcia odôvodňuje."]}]}]}];
